import type { BankQuestion } from "@/lib/bank";

/** Profit and Loss (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-profit-loss-1","question":"An article bought for ₹500 is sold for ₹600. The profit percentage is:","options":["10%","16.67%","20%","25%"],"answer":2,"explanation":"Profit = ₹100 on a cost of ₹500, so profit % = 100/500 × 100 = 20%. 16.67% divides by the selling price (100/600), the most common base error.","difficulty":"moderate","questionHi":"₹500 में खरीदी गई एक वस्तु ₹600 में बेची जाती है। लाभ प्रतिशत है:","optionsHi":["10%","16.67%","20%","25%"],"explanationHi":"₹500 के क्रय मूल्य पर लाभ ₹100 है, अतः लाभ % = 100/500 × 100 = 20%। 16.67% में विक्रय मूल्य से भाग दिया गया है (100/600), जो सबसे आम आधार संबंधी भूल है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-2","question":"Profit and loss percentages are always calculated on the:","options":["Selling price","Marked price","Cost price","Discount"],"answer":2,"explanation":"Unless stated otherwise, profit % and loss % are on the cost price.","difficulty":"easy","questionHi":"लाभ और हानि का प्रतिशत हमेशा किस पर निकाला जाता है:","optionsHi":["विक्रय मूल्य","अंकित मूल्य","क्रय मूल्य","छूट"],"explanationHi":"जब तक अन्यथा न कहा जाए, लाभ % और हानि % क्रय मूल्य पर निकाले जाते हैं।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-3","question":"A shopkeeper allows a 10% discount on a marked price of ₹800. The selling price is:","options":["₹700","₹720","₹780","₹790"],"answer":1,"explanation":"Discount = 10% of 800 = ₹80, so SP = ₹720. ₹700 subtracts a flat ₹100, and ₹790 subtracts only ₹10.","difficulty":"moderate","questionHi":"एक दुकानदार ₹800 के अंकित मूल्य पर 10% की छूट देता है। विक्रय मूल्य है:","optionsHi":["₹700","₹720","₹780","₹790"],"explanationHi":"छूट = 800 का 10% = ₹80, अतः विक्रय मूल्य = ₹720। ₹700 में सीधे ₹100 घटा दिए गए हैं, और ₹790 में केवल ₹10 घटाए गए हैं।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-4","question":"The cost price of 20 articles equals the selling price of 16 articles. The profit percentage is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"Let CP of each article be ₹1: CP = 20, SP of 16 = 20, so SP of each = 1.25. Profit = 25%.","difficulty":"very-hard","questionHi":"20 वस्तुओं का क्रय मूल्य 16 वस्तुओं के विक्रय मूल्य के बराबर है। लाभ प्रतिशत है:","optionsHi":["20%","25%","30%","40%"],"explanationHi":"माना प्रत्येक वस्तु का क्रय मूल्य ₹1 है: क्रय मूल्य = 20, 16 का विक्रय मूल्य = 20, अतः प्रत्येक का विक्रय मूल्य = 1.25। लाभ = 25%।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-5","question":"An article bought for ₹400 is sold for ₹500. The profit percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"Profit = ₹100 on a cost of ₹400, so profit % = 25%. 20% divides by the selling price ₹500 instead of the cost.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"₹400 में खरीदी गई एक वस्तु ₹500 में बेची जाती है। लाभ प्रतिशत है:","optionsHi":["20%","25%","30%","40%"],"explanationHi":"₹400 के क्रय मूल्य पर लाभ ₹100 है, अतः लाभ % = 25%। 20% में क्रय मूल्य के बजाय विक्रय मूल्य ₹500 से भाग दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-6","question":"A shopkeeper marks an article 40% above cost and gives a 20% discount. His profit percent is:","options":["12%","16%","20%","24%"],"answer":0,"explanation":"SP = 1.4 × 0.8 = 1.12 × CP, so the profit is 12%. 20% just subtracts 40 − 20; the discount is taken on the marked price, which is already 40% above cost.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"एक दुकानदार किसी वस्तु का मूल्य क्रय मूल्य से 40% अधिक अंकित करता है और 20% की छूट देता है। उसका लाभ प्रतिशत है:","optionsHi":["12%","16%","20%","24%"],"explanationHi":"विक्रय मूल्य = 1.4 × 0.8 = 1.12 × क्रय मूल्य, अतः लाभ 12% है। 20% में केवल 40 − 20 घटाया गया है; छूट अंकित मूल्य पर ली जाती है, जो पहले से ही क्रय मूल्य से 40% अधिक है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-7","question":"The cost price of 20 articles equals the selling price of 16 articles. The gain percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"CP of 20 = SP of 16, so SP/CP = 20/16 = 1.25: a 25% gain. 20% divides the 4-article gap by 20 (the SP side) instead of 16.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"20 वस्तुओं का क्रय मूल्य 16 वस्तुओं के विक्रय मूल्य के बराबर है। लाभ प्रतिशत है:","optionsHi":["20%","25%","30%","40%"],"explanationHi":"20 का क्रय मूल्य = 16 का विक्रय मूल्य, अतः विक्रय मूल्य/क्रय मूल्य = 20/16 = 1.25: 25% का लाभ। 20% में 4 वस्तुओं के अंतर को 16 के बजाय 20 (विक्रय मूल्य की ओर) से भाग दिया गया है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-8","question":"A dishonest dealer sells at cost price but uses a weight of 800 g for 1 kg. His gain percent is:","options":["20%","25%","30%","40%"],"answer":1,"explanation":"He gives 800 g but charges for 1,000 g, so gain = 200/800 × 100 = 25%. 20% wrongly divides the 200 g shortfall by 1,000 g instead of by what he actually gives.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक बेईमान व्यापारी क्रय मूल्य पर ही बेचता है लेकिन 1 kg के स्थान पर 800 g का बाट प्रयोग करता है। उसका लाभ प्रतिशत है:","optionsHi":["20%","25%","30%","40%"],"explanationHi":"वह 800 g देता है लेकिन 1,000 g का मूल्य लेता है, अतः लाभ = 200/800 × 100 = 25%। 20% में 200 g की कमी को वह जो वास्तव में देता है उससे भाग देने के बजाय 1,000 g से भाग दिया गया है।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-9","question":"An article is sold for ₹414 at a loss of 8%. Its cost price is:","options":["₹450","₹460","₹380","₹447"],"answer":0,"explanation":"SP = 92% of CP, so CP = 414/0.92 = ₹450. Adding 8% of 414 (₹447) is the wrong-base slip.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"एक वस्तु 8% की हानि पर ₹414 में बेची जाती है। उसका क्रय मूल्य है:","optionsHi":["₹450","₹460","₹380","₹447"],"explanationHi":"विक्रय मूल्य = क्रय मूल्य का 92%, अतः क्रय मूल्य = 414/0.92 = ₹450। 414 का 8% जोड़ना (₹447) गलत आधार लेने की भूल है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-10","question":"The marked price of a shirt is ₹1,200 and a 15% discount is allowed. The selling price is:","options":["₹1,020","₹1,000","₹1,050","₹1,080"],"answer":0,"explanation":"Discount = 15% of 1,200 = ₹180, so SP = 1,200 − 180 = ₹1,020.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"एक कमीज़ का अंकित मूल्य ₹1,200 है और 15% की छूट दी जाती है। विक्रय मूल्य है:","optionsHi":["₹1,020","₹1,000","₹1,050","₹1,080"],"explanationHi":"छूट = 1,200 का 15% = ₹180, अतः विक्रय मूल्य = 1,200 − 180 = ₹1,020।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-11","question":"A trader sells an article at a loss of 20%. Had he sold it for ₹200 more, he would have gained 5%. The cost price is:","options":["₹1,000","₹800","₹600","₹750"],"answer":1,"explanation":"The two selling prices differ by 20% + 5% = 25% of CP = ₹200, so CP = ₹800.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यापारी किसी वस्तु को 20% की हानि पर बेचता है। यदि वह इसे ₹200 अधिक में बेचता, तो उसे 5% का लाभ होता। क्रय मूल्य है:","optionsHi":["₹1,000","₹800","₹600","₹750"],"explanationHi":"दोनों विक्रय मूल्यों का अंतर क्रय मूल्य का 20% + 5% = 25% = ₹200 है, अतः क्रय मूल्य = ₹800।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-12","question":"By selling a watch for ₹1,080 a dealer gains 20%. To gain 25% he should sell it for:","options":["₹1,100","₹1,350","₹1,125","₹1,150"],"answer":2,"explanation":"CP = 1,080/1.2 = ₹900; 125% of 900 = ₹1,125. Adding 5% of 1,080 gives the wrong ₹1,134.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक घड़ी ₹1,080 में बेचने पर एक व्यापारी को 20% का लाभ होता है। 25% लाभ पाने के लिए उसे इसे किस मूल्य पर बेचना चाहिए:","optionsHi":["₹1,100","₹1,350","₹1,125","₹1,150"],"explanationHi":"क्रय मूल्य = 1,080/1.2 = ₹900; 900 का 125% = ₹1,125। 1,080 का 5% जोड़ने पर गलत ₹1,134 आता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-13","question":"Two articles are sold for ₹1,200 each, one at a profit of 20% and the other at a loss of 20%. The overall result is:","options":["₹100 profit","no profit, no loss","₹96 loss","₹100 loss"],"answer":3,"explanation":"CP₁ = 1,200/1.2 = ₹1,000 and CP₂ = 1,200/0.8 = ₹1,500. Total CP ₹2,500, total SP ₹2,400: a loss of ₹100 (4% of CP). Equal SPs with equal percent gain and loss always give a loss.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दो वस्तुएँ ₹1,200 प्रत्येक में बेची जाती हैं, एक 20% के लाभ पर और दूसरी 20% की हानि पर। कुल परिणाम है:","optionsHi":["₹100 का लाभ","न लाभ, न हानि","₹96 की हानि","₹100 की हानि"],"explanationHi":"क्रय मूल्य₁ = 1,200/1.2 = ₹1,000 और क्रय मूल्य₂ = 1,200/0.8 = ₹1,500। कुल क्रय मूल्य ₹2,500, कुल विक्रय मूल्य ₹2,400: ₹100 की हानि (क्रय मूल्य का 4%)। बराबर विक्रय मूल्य पर बराबर प्रतिशत लाभ और हानि से हमेशा हानि होती है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-14","question":"Successive discounts of 20% and 10% are given on a marked price of ₹500. The selling price is:","options":["₹370","₹400","₹350","₹360"],"answer":3,"explanation":"SP = 500 × 0.8 × 0.9 = ₹360. Adding the discounts to 30% gives the wrong ₹350.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"₹500 के अंकित मूल्य पर 20% और 10% की क्रमिक छूट दी जाती है। विक्रय मूल्य है:","optionsHi":["₹370","₹400","₹350","₹360"],"explanationHi":"विक्रय मूल्य = 500 × 0.8 × 0.9 = ₹360। छूटों को जोड़कर 30% लेने पर गलत ₹350 आता है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-15","question":"A shopkeeper marks his goods 50% above cost price, allows a 20% discount and also uses a 900 g weight in place of 1 kg. His profit percent is:","options":["25%","30%","20%","33⅓%"],"answer":3,"explanation":"Per kg price charged = 1.5 × 0.8 = 1.2 × CP of 1 kg, but he gives only 0.9 kg costing 0.9 CP. Profit = (1.2 − 0.9)/0.9 = 1/3 = 33⅓%. Ignoring the false weight gives 20%.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार अपना माल क्रय मूल्य से 50% अधिक अंकित करता है, 20% की छूट देता है और साथ ही 1 kg के स्थान पर 900 g का बाट भी प्रयोग करता है। उसका लाभ प्रतिशत है:","optionsHi":["25%","30%","20%","33⅓%"],"explanationHi":"प्रति kg लिया गया मूल्य = 1.5 × 0.8 = 1 kg के क्रय मूल्य का 1.2 गुना, लेकिन वह केवल 0.9 kg देता है जिसकी लागत 0.9 क्रय मूल्य है। लाभ = (1.2 − 0.9)/0.9 = 1/3 = 33⅓%। झूठे बाट को अनदेखा करने पर 20% आता है।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-16","question":"A retailer buys goods at a 20% discount on the list price and sells them at 10% above the list price. His profit percent is:","options":["40%","30%","37.5%","32%"],"answer":2,"explanation":"Take list price 100: CP = 80, SP = 110, profit = 30 on 80 = 37.5%. Taking 30 on 100 gives the wrong 30%.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक खुदरा विक्रेता माल सूची मूल्य पर 20% की छूट से खरीदता है और सूची मूल्य से 10% अधिक पर बेचता है। उसका लाभ प्रतिशत है:","optionsHi":["40%","30%","37.5%","32%"],"explanationHi":"सूची मूल्य 100 लें: क्रय मूल्य = 80, विक्रय मूल्य = 110, लाभ = 80 पर 30 = 37.5%। 100 पर 30 लेने से गलत 30% आता है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-17","question":"A dealer sells an article at 10% profit. Had he bought it for 10% less and sold it for ₹14 more, his profit would have been 25%. The cost price is:","options":["₹640","₹500","₹600","₹560"],"answer":3,"explanation":"Let CP = x: SP = 1.1x. New CP = 0.9x, new SP = 1.25 × 0.9x = 1.125x. So 1.125x − 1.1x = 14, 0.025x = 14, x = ₹560. Check: 504 × 1.25 = 630 = 616 + 14.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यापारी किसी वस्तु को 10% लाभ पर बेचता है। यदि वह इसे 10% कम में खरीदता और ₹14 अधिक में बेचता, तो उसका लाभ 25% होता। क्रय मूल्य है:","optionsHi":["₹640","₹500","₹600","₹560"],"explanationHi":"माना क्रय मूल्य = x: विक्रय मूल्य = 1.1x। नया क्रय मूल्य = 0.9x, नया विक्रय मूल्य = 1.25 × 0.9x = 1.125x। अतः 1.125x − 1.1x = 14, 0.025x = 14, x = ₹560। जाँच: 504 × 1.25 = 630 = 616 + 14।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-18","question":"A shopkeeper marks his goods so that even after allowing a 25% discount he gains 20%. The marked price is above the cost price by:","options":["55%","45%","60%","50%"],"answer":2,"explanation":"0.75 × MP = 1.2 × CP, so MP = 1.6 CP, i.e. 60% above cost. Adding 25% + 20% = 45% is the slip.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार अपना माल इस प्रकार अंकित करता है कि 25% की छूट देने के बाद भी उसे 20% का लाभ हो। अंकित मूल्य क्रय मूल्य से अधिक है:","optionsHi":["55%","45%","60%","50%"],"explanationHi":"0.75 × अंकित मूल्य = 1.2 × क्रय मूल्य, अतः अंकित मूल्य = 1.6 क्रय मूल्य, अर्थात् क्रय मूल्य से 60% अधिक। 25% + 20% = 45% जोड़ना भूल है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-19","question":"The profit earned by selling an article for ₹1,440 equals the loss incurred by selling it for ₹1,200. To gain 15% it should be sold for:","options":["₹1,480","₹1,560","₹1,500","₹1,518"],"answer":3,"explanation":"CP is midway: (1,440 + 1,200)/2 = ₹1,320. SP for 15% gain = 1.15 × 1,320 = ₹1,518.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक वस्तु को ₹1,440 में बेचने पर होने वाला लाभ, उसे ₹1,200 में बेचने पर होने वाली हानि के बराबर है। 15% लाभ पाने के लिए इसे किस मूल्य पर बेचना चाहिए:","optionsHi":["₹1,480","₹1,560","₹1,500","₹1,518"],"explanationHi":"क्रय मूल्य ठीक बीच में है: (1,440 + 1,200)/2 = ₹1,320। 15% लाभ के लिए विक्रय मूल्य = 1.15 × 1,320 = ₹1,518।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-20","question":"A fruit seller buys oranges at 5 for ₹4 and sells them at 4 for ₹5. His gain percent is:","options":["25%","50%","56.25%","60%"],"answer":2,"explanation":"CP per orange = ₹0.80, SP = ₹1.25. Gain = 0.45/0.80 = 56.25%. The naive 25% (5 vs 4) ignores that the base is the cost.","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"एक फल विक्रेता संतरे ₹4 के 5 की दर से खरीदता है और ₹5 के 4 की दर से बेचता है। उसका लाभ प्रतिशत है:","optionsHi":["25%","50%","56.25%","60%"],"explanationHi":"प्रति संतरा क्रय मूल्य = ₹0.80, विक्रय मूल्य = ₹1.25। लाभ = 0.45/0.80 = 56.25%। सीधा 25% (5 बनाम 4) इस बात को अनदेखा करता है कि आधार क्रय मूल्य है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-21","question":"Three successive discounts of 10%, 20% and 25% are equivalent to a single discount of:","options":["50%","46%","55%","54%"],"answer":1,"explanation":"Net price factor = 0.9 × 0.8 × 0.75 = 0.54, so the single discount = 1 − 0.54 = 46%. 54% is what remains, not the discount; 55% is the sum.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"10%, 20% और 25% की तीन क्रमिक छूटें किस एकल छूट के समतुल्य हैं:","optionsHi":["50%","46%","55%","54%"],"explanationHi":"शुद्ध मूल्य गुणक = 0.9 × 0.8 × 0.75 = 0.54, अतः एकल छूट = 1 − 0.54 = 46%। 54% वह है जो बचता है, छूट नहीं; 55% योगफल है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-22","question":"A dealer buys 100 kg of potatoes at ₹40 per kg. 20% of the stock rots. At what price per kg must he sell the rest to make an overall profit of 20%?","options":["₹58","₹48","₹60","₹50"],"answer":2,"explanation":"Cost = ₹4,000; required revenue = ₹4,800 from the 80 kg that remain, so ₹60 per kg. ₹48 ignores the loss of stock.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यापारी ₹40 प्रति kg की दर से 100 kg आलू खरीदता है। 20% स्टॉक सड़ जाता है। कुल मिलाकर 20% का लाभ कमाने के लिए उसे शेष को प्रति kg किस मूल्य पर बेचना चाहिए?","optionsHi":["₹58","₹48","₹60","₹50"],"explanationHi":"लागत = ₹4,000; बचे हुए 80 kg से आवश्यक राजस्व = ₹4,800, अतः ₹60 प्रति kg। ₹48 में स्टॉक की हानि को अनदेखा किया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-23","question":"The marked price of an article is ₹300. A dealer gives a 10% discount and also one article free with every 8 bought. If he still gains 20%, his cost price per article is:","options":["₹200","₹180","₹240","₹225"],"answer":0,"explanation":"A customer pays 8 × 270 = ₹2,160 and gets 9 articles. 2,160 = 1.2 × 9 × CP, so CP = 2,160/10.8 = ₹200.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक वस्तु का अंकित मूल्य ₹300 है। एक व्यापारी 10% की छूट देता है और हर 8 खरीदने पर एक वस्तु मुफ़्त भी देता है। यदि फिर भी उसे 20% का लाभ होता है, तो प्रति वस्तु उसका क्रय मूल्य है:","optionsHi":["₹200","₹180","₹240","₹225"],"explanationHi":"ग्राहक 8 × 270 = ₹2,160 देता है और 9 वस्तुएँ पाता है। 2,160 = 1.2 × 9 × क्रय मूल्य, अतः क्रय मूल्य = 2,160/10.8 = ₹200।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-24","question":"How many of the following statements are correct?\n1. Two articles sold at the same price, one at x% gain and the other at x% loss, always give an overall loss.\n2. Discount is always calculated on the cost price.\n3. Two successive discounts of 10% each equal a single discount of 20%.\n4. If the cost price of 12 articles equals the selling price of 10 articles, the gain is 20%.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"1 is true (loss of x²/100 %). 2 is false: discount is on the marked price. 3 is false: 0.9 × 0.9 = 0.81, a 19% discount. 4 is true: SP/CP = 12/10 = 1.2. Two statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. एक ही मूल्य पर बेची गई दो वस्तुएँ, एक x% लाभ पर और दूसरी x% हानि पर, हमेशा कुल हानि देती हैं।\n2. छूट हमेशा क्रय मूल्य पर निकाली जाती है।\n3. 10%-10% की दो क्रमिक छूटें 20% की एकल छूट के बराबर होती हैं।\n4. यदि 12 वस्तुओं का क्रय मूल्य 10 वस्तुओं के विक्रय मूल्य के बराबर है, तो लाभ 20% है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"1 सही है (x²/100 % की हानि)। 2 गलत है: छूट अंकित मूल्य पर होती है। 3 गलत है: 0.9 × 0.9 = 0.81, यानी 19% की छूट। 4 सही है: विक्रय मूल्य/क्रय मूल्य = 12/10 = 1.2। दो कथन सही हैं।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-25","question":"A dishonest grocer cheats by 10% while buying and by 10% while selling, using false weights, and professes to sell at cost price. His gain percent is:","options":["20%","22 2/9 %","21%","19%"],"answer":1,"explanation":"Buying, he gets 1,100 g while paying for 1,000 g; selling, he gives 900 g while charging for 1,000 g. On 1,100 g bought for ₹1,000 he collects 1,100/900 × 1,000 = ₹1,222.2, a gain of 22 2/9 %. Simply adding 10 + 10 = 20% is wrong.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक बेईमान किराना व्यापारी खरीदते समय 10% और बेचते समय 10% झूठे बाटों से धोखा देता है, और क्रय मूल्य पर बेचने का दावा करता है। उसका लाभ प्रतिशत है:","optionsHi":["20%","22 2/9 %","21%","19%"],"explanationHi":"खरीदते समय वह 1,000 g के पैसे देकर 1,100 g पाता है; बेचते समय वह 1,000 g का मूल्य लेकर 900 g देता है। ₹1,000 में खरीदे 1,100 g पर वह 1,100/900 × 1,000 = ₹1,222.2 वसूलता है, यानी 22 2/9 % का लाभ। 10 + 10 = 20% जोड़ना गलत है।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-26","question":"A sells a cycle to B at 20% profit, B sells it to C at 25% loss and C sells it to D at 60% profit. If D pays ₹1,728, A's cost price was:","options":["₹1,440","₹1,200","₹1,080","₹1,115"],"answer":1,"explanation":"Net factor = 1.2 × 0.75 × 1.6 = 1.44, so A's CP = 1,728/1.44 = ₹1,200. Adding the percentages (20 − 25 + 60 = 55%) and dividing by 1.55 gives the wrong ₹1,115.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"A एक साइकिल B को 20% लाभ पर बेचता है, B इसे C को 25% हानि पर बेचता है और C इसे D को 60% लाभ पर बेचता है। यदि D ₹1,728 देता है, तो A का क्रय मूल्य था:","optionsHi":["₹1,440","₹1,200","₹1,080","₹1,115"],"explanationHi":"शुद्ध गुणक = 1.2 × 0.75 × 1.6 = 1.44, अतः A का क्रय मूल्य = 1,728/1.44 = ₹1,200। प्रतिशतों को जोड़कर (20 − 25 + 60 = 55%) 1.55 से भाग देने पर गलत ₹1,115 आता है।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-27","question":"A man sells a book for ₹24 and his profit percent is numerically equal to the cost price in rupees. The cost price is:","options":["₹20","₹24","₹16","₹12"],"answer":0,"explanation":"Let CP = x and profit = x%. SP = x + x²/100 = 24, so x² + 100x − 2,400 = 0, (x + 120)(x − 20) = 0, x = 20. Check: 20 + 20% of 20 = 24.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यक्ति एक पुस्तक ₹24 में बेचता है और उसका लाभ प्रतिशत संख्यात्मक रूप से रुपयों में क्रय मूल्य के बराबर है। क्रय मूल्य है:","optionsHi":["₹20","₹24","₹16","₹12"],"explanationHi":"माना क्रय मूल्य = x और लाभ = x%। विक्रय मूल्य = x + x²/100 = 24, अतः x² + 100x − 2,400 = 0, (x + 120)(x − 20) = 0, x = 20। जाँच: 20 + 20 का 20% = 24।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-28","question":"A merchant marks his goods 40% above cost. He sells one-third of the stock at the marked price, half of the remainder at a 20% discount and the rest at a 40% discount. His overall profit percent is:","options":["12%","20%","10%","16%"],"answer":0,"explanation":"Take 3 units costing ₹100 each (MP ₹140). Revenue = 140 + 140 × 0.8 + 140 × 0.6 = 140 + 112 + 84 = ₹336 against cost ₹300, profit 12%.","difficulty":"very-hard","source":"SSC CGL · SBI PO","questionHi":"एक व्यापारी अपना माल क्रय मूल्य से 40% अधिक अंकित करता है। वह एक-तिहाई स्टॉक अंकित मूल्य पर, शेष का आधा 20% की छूट पर और बाकी 40% की छूट पर बेचता है। उसका कुल लाभ प्रतिशत है:","optionsHi":["12%","20%","10%","16%"],"explanationHi":"₹100 प्रति इकाई की लागत वाली 3 इकाइयाँ लें (अंकित मूल्य ₹140)। राजस्व = 140 + 140 × 0.8 + 140 × 0.6 = 140 + 112 + 84 = ₹336, लागत ₹300 के सामने, लाभ 12%।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-29","question":"A man buys a pen for ₹80 and sells it for ₹92. What is his profit percent?","options":["12%","15%","13%","12.5%"],"answer":1,"explanation":"Profit = 92 − 80 = 12. Profit % = 12/80 × 100 = 15%. 13% wrongly divides by the selling price.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"एक व्यक्ति एक कलम ₹80 में खरीदता है और ₹92 में बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["12%","15%","13%","12.5%"],"explanationHi":"लाभ = 92 − 80 = 12। लाभ % = 12/80 × 100 = 15%। 13% में गलती से विक्रय मूल्य से भाग दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-30","question":"By selling an article for ₹1,425 a trader loses 5%. At what price should he sell it to gain 10%?","options":["₹1,650","₹1,567.50","₹1,600","₹1,575"],"answer":0,"explanation":"CP = 1,425 ÷ 0.95 = 1,500. For 10% gain, SP = 1,500 × 1.1 = ₹1,650. ₹1,567.50 adds 10% to the loss-making SP instead of the CP.","difficulty":"moderate","source":"SSC CGL","questionHi":"एक वस्तु ₹1,425 में बेचने पर एक व्यापारी को 5% की हानि होती है। 10% का लाभ पाने के लिए उसे इसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹1,650","₹1,567.50","₹1,600","₹1,575"],"explanationHi":"क्रय मूल्य = 1,425 ÷ 0.95 = 1,500। 10% लाभ के लिए विक्रय मूल्य = 1,500 × 1.1 = ₹1,650। ₹1,567.50 में क्रय मूल्य के बजाय हानि वाले विक्रय मूल्य में 10% जोड़ा गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-31","question":"A trader marks his goods 30% above cost and allows a 10% discount. If his profit on an article is ₹68, what is its cost price?","options":["₹340","₹500","₹680","₹400"],"answer":3,"explanation":"SP = 1.3 × 0.9 × CP = 1.17 CP, so profit = 17% of CP = 68 and CP = ₹400. Taking profit as 30 − 10 = 20% gives ₹340.","difficulty":"moderate","source":"SSC CGL","questionHi":"एक व्यापारी अपना माल क्रय मूल्य से 30% अधिक अंकित करता है और 10% की छूट देता है। यदि किसी वस्तु पर उसका लाभ ₹68 है, तो उसका क्रय मूल्य क्या है?","optionsHi":["₹340","₹500","₹680","₹400"],"explanationHi":"विक्रय मूल्य = 1.3 × 0.9 × क्रय मूल्य = 1.17 क्रय मूल्य, अतः लाभ = क्रय मूल्य का 17% = 68 और क्रय मूल्य = ₹400। लाभ को 30 − 10 = 20% लेने पर ₹340 आता है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-32","question":"By selling 33 metres of cloth, a shopkeeper gains the selling price of 11 metres. What is his gain percent?","options":["33⅓%","25%","50%","66⅔%"],"answer":2,"explanation":"Profit = SP of 11 m, so CP of 33 m = SP of 33 m − SP of 11 m = SP of 22 m. Gain = 11/22 × 100 = 50%. 33⅓% divides by 33 instead of 22.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"33 मीटर कपड़ा बेचने पर एक दुकानदार को 11 मीटर के विक्रय मूल्य के बराबर लाभ होता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["33⅓%","25%","50%","66⅔%"],"explanationHi":"लाभ = 11 m का विक्रय मूल्य, अतः 33 m का क्रय मूल्य = 33 m का विक्रय मूल्य − 11 m का विक्रय मूल्य = 22 m का विक्रय मूल्य। लाभ = 11/22 × 100 = 50%। 33⅓% में 22 के बजाय 33 से भाग दिया गया है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-33","question":"A man buys two cows for ₹36,000. He sells one at a 20% profit and the other at a 10% loss, and on the whole neither gains nor loses. What did the cheaper cow cost?","options":["₹18,000","₹12,000","₹24,000","₹15,000"],"answer":1,"explanation":"Let the first cost x. 0.2x = 0.1(36,000 − x) → 0.3x = 3,600 → x = 12,000, the other ₹24,000. The cheaper cow (₹12,000) is the one sold at 20% profit.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"एक व्यक्ति दो गायें ₹36,000 में खरीदता है। वह एक को 20% लाभ पर और दूसरी को 10% हानि पर बेचता है, और कुल मिलाकर न लाभ होता है, न हानि। सस्ती गाय की कीमत क्या थी?","optionsHi":["₹18,000","₹12,000","₹24,000","₹15,000"],"explanationHi":"माना पहली की कीमत x है। 0.2x = 0.1(36,000 − x) → 0.3x = 3,600 → x = 12,000, दूसरी ₹24,000 की। सस्ती गाय (₹12,000) वही है जो 20% लाभ पर बेची गई।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-34","question":"A shopkeeper marks an article 25% above cost and offers 'buy 4, get 1 free'. What is his overall profit or loss percent?","options":["No profit, no loss","5% profit","25% profit","20% loss"],"answer":0,"explanation":"For 5 articles costing 5C he receives the marked price of 4: 4 × 1.25C = 5C. Revenue equals cost, so no profit and no loss. The free item is a 20% discount, which cancels the 25% mark-up exactly.","difficulty":"hard","source":"SSC CGL","questionHi":"एक दुकानदार किसी वस्तु को क्रय मूल्य से 25% अधिक अंकित करता है और '4 खरीदें, 1 मुफ़्त पाएँ' की पेशकश करता है। उसका कुल लाभ या हानि प्रतिशत क्या है?","optionsHi":["न लाभ, न हानि","5% लाभ","25% लाभ","20% हानि"],"explanationHi":"5C लागत वाली 5 वस्तुओं के लिए उसे 4 का अंकित मूल्य मिलता है: 4 × 1.25C = 5C। राजस्व लागत के बराबर है, अतः न लाभ, न हानि। मुफ़्त वस्तु 20% की छूट है, जो 25% की अंकन वृद्धि को ठीक निरस्त कर देती है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-35","question":"A dishonest dealer claims to sell at a 10% loss but gives only 750 g for every kilogram. What is his actual gain or loss percent?","options":["15% gain","10% loss","12.5% gain","20% gain"],"answer":3,"explanation":"Let 1 kg cost ₹100. He charges ₹90 (10% loss on 1 kg) but hands over 750 g, which cost him ₹75. Gain = 15/75 × 100 = 20%. 15% divides by 100 instead of 75.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक बेईमान व्यापारी 10% हानि पर बेचने का दावा करता है लेकिन प्रत्येक किलोग्राम के बदले केवल 750 g देता है। उसका वास्तविक लाभ या हानि प्रतिशत क्या है?","optionsHi":["15% लाभ","10% हानि","12.5% लाभ","20% लाभ"],"explanationHi":"माना 1 kg की लागत ₹100 है। वह ₹90 लेता है (1 kg पर 10% हानि) लेकिन 750 g देता है, जिसकी उसे लागत ₹75 पड़ी। लाभ = 15/75 × 100 = 20%। 15% में 75 के बजाय 100 से भाग दिया गया है।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-36","question":"A sells a scooter to B at a 25% profit, B sells it to C at a 10% loss, and C sells it to D for ₹1,350, making a profit of ₹225. What was A's cost price?","options":["₹1,080","₹1,200","₹1,000","₹960"],"answer":2,"explanation":"C's cost = 1,350 − 225 = 1,125 = B's SP. B's cost = 1,125 ÷ 0.9 = 1,250 = A's SP. A's cost = 1,250 ÷ 1.25 = ₹1,000.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A एक स्कूटर B को 25% लाभ पर बेचता है, B इसे C को 10% हानि पर बेचता है, और C इसे D को ₹1,350 में बेचकर ₹225 का लाभ कमाता है। A का क्रय मूल्य क्या था?","optionsHi":["₹1,080","₹1,200","₹1,000","₹960"],"explanationHi":"C का क्रय मूल्य = 1,350 − 225 = 1,125 = B का विक्रय मूल्य। B का क्रय मूल्य = 1,125 ÷ 0.9 = 1,250 = A का विक्रय मूल्य। A का क्रय मूल्य = 1,250 ÷ 1.25 = ₹1,000।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-37","question":"A shopkeeper allows a 20% discount on the marked price and still gains 25% on an article costing ₹640. What is the marked price, and what would his profit percent be if he allowed only a 10% discount?","options":["₹1,000; 35%","₹1,000; 40.625%","₹960; 40.625%","₹1,000; 45%"],"answer":1,"explanation":"SP = 640 × 1.25 = 800 = 0.8 × MP, so MP = ₹1,000. With 10% off, SP = 900, profit = 260/640 × 100 = 40.625%. Adding 25% + 10% = 35% is the shortcut slip.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक दुकानदार अंकित मूल्य पर 20% की छूट देता है और ₹640 में खरीदी वस्तु पर फिर भी 25% का लाभ कमाता है। अंकित मूल्य क्या है, और यदि वह केवल 10% की छूट देता तो उसका लाभ प्रतिशत क्या होता?","optionsHi":["₹1,000; 35%","₹1,000; 40.625%","₹960; 40.625%","₹1,000; 45%"],"explanationHi":"विक्रय मूल्य = 640 × 1.25 = 800 = 0.8 × अंकित मूल्य, अतः अंकित मूल्य = ₹1,000। 10% छूट पर विक्रय मूल्य = 900, लाभ = 260/640 × 100 = 40.625%। 25% + 10% = 35% जोड़ना शॉर्टकट की भूल है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-38","question":"A trader buys 40 kg of rice at ₹30 per kg and 80 kg at ₹36 per kg, mixes them and wants a 20% profit on the whole. At what price per kg must he sell the mixture?","options":["₹40.80","₹39.60","₹43.20","₹40.00"],"answer":0,"explanation":"Total cost = 40×30 + 80×36 = 1,200 + 2,880 = 4,080 for 120 kg, i.e. ₹34 per kg. With 20% profit: 34 × 1.2 = ₹40.80. ₹39.60 uses the simple average 33 instead of the weighted 34.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक व्यापारी ₹30 प्रति kg की दर से 40 kg चावल और ₹36 प्रति kg की दर से 80 kg चावल खरीदता है, उन्हें मिलाता है और पूरे पर 20% का लाभ चाहता है। उसे मिश्रण को प्रति kg किस मूल्य पर बेचना चाहिए?","optionsHi":["₹40.80","₹39.60","₹43.20","₹40.00"],"explanationHi":"कुल लागत = 40×30 + 80×36 = 1,200 + 2,880 = 120 kg के लिए 4,080, अर्थात् ₹34 प्रति kg। 20% लाभ के साथ: 34 × 1.2 = ₹40.80। ₹39.60 में भारित 34 के बजाय साधारण औसत 33 लिया गया है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-39","question":"An article is sold for ₹840 at a profit of 12%. What is its cost price?","options":["₹728","₹739.20","₹760","₹750"],"answer":3,"explanation":"CP = 840 ÷ 1.12 = ₹750. Taking 12% off ₹840 (₹739.20) is wrong because profit is a percent of CP.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक वस्तु 12% के लाभ पर ₹840 में बेची जाती है। उसका क्रय मूल्य क्या है?","optionsHi":["₹728","₹739.20","₹760","₹750"],"explanationHi":"क्रय मूल्य = 840 ÷ 1.12 = ₹750। ₹840 में से 12% घटाना (₹739.20) गलत है क्योंकि लाभ क्रय मूल्य का प्रतिशत होता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-40","question":"An article marked at ₹2,500 is sold for ₹2,125. What is the rate of discount?","options":["12.5%","17.6%","15%","20%"],"answer":2,"explanation":"Discount = ₹375, and discount is a percent of the marked price: 375/2,500 × 100 = 15%. 17.6% wrongly divides by the selling price.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹2,500 अंकित मूल्य वाली एक वस्तु ₹2,125 में बेची जाती है। छूट की दर क्या है?","optionsHi":["12.5%","17.6%","15%","20%"],"explanationHi":"छूट = ₹375, और छूट अंकित मूल्य का प्रतिशत होती है: 375/2,500 × 100 = 15%। 17.6% में गलती से विक्रय मूल्य से भाग दिया गया है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-41","question":"An article bought for ₹1,250 is sold for ₹1,100. What is the loss percent?","options":["15%","12%","10%","13.64%"],"answer":1,"explanation":"Loss = ₹150 and loss % = 150/1,250 × 100 = 12%. Dividing by the selling price gives 13.64%.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"₹1,250 में खरीदी गई एक वस्तु ₹1,100 में बेची जाती है। हानि प्रतिशत क्या है?","optionsHi":["15%","12%","10%","13.64%"],"explanationHi":"हानि = ₹150 और हानि % = 150/1,250 × 100 = 12%। विक्रय मूल्य से भाग देने पर 13.64% आता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-42","question":"A trader buys an article for ₹800, sells it at a 25% profit and charges 12% GST on the selling price. How much does the customer pay?","options":["₹1,096","₹1,120","₹1,140","₹1,100"],"answer":1,"explanation":"SP = 800 × 1.25 = ₹1,000; with 12% GST the customer pays 1,000 × 1.12 = ₹1,120. Adding 25% + 12% = 37% to ₹800 (₹1,096) ignores that GST is charged on the higher price.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"एक व्यापारी एक वस्तु ₹800 में खरीदता है, उसे 25% लाभ पर बेचता है और विक्रय मूल्य पर 12% GST लगाता है। ग्राहक कितना भुगतान करता है?","optionsHi":["₹1,096","₹1,120","₹1,140","₹1,100"],"explanationHi":"विक्रय मूल्य = 800 × 1.25 = ₹1,000; 12% GST के साथ ग्राहक 1,000 × 1.12 = ₹1,120 देता है। ₹800 में 25% + 12% = 37% जोड़ना (₹1,096) इस बात को अनदेखा करता है कि GST अधिक मूल्य पर लगता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-43","question":"A shopkeeper makes a profit of 20% on the selling price. What is his profit as a percent of the cost price?","options":["24%","25%","16 2/3%","20%"],"answer":1,"explanation":"If SP = 100, profit = 20 and CP = 80, so profit on CP = 20/80 × 100 = 25%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार विक्रय मूल्य पर 20% का लाभ कमाता है। क्रय मूल्य के प्रतिशत के रूप में उसका लाभ कितना है?","optionsHi":["24%","25%","16 2/3%","20%"],"explanationHi":"यदि विक्रय मूल्य = 100, तो लाभ = 20 और क्रय मूल्य = 80, अतः क्रय मूल्य पर लाभ = 20/80 × 100 = 25%।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-44","question":"By selling 36 oranges for ₹180 a vendor loses 10%. How many oranges must he sell for ₹180 to gain 8%?","options":["33","30","32","28"],"answer":1,"explanation":"SP of one orange = ₹5 = 0.9 × CP, so CP = ₹50/9. For an 8% gain, SP = 1.08 × 50/9 = ₹6, so he must sell 180 ÷ 6 = 30 oranges.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"36 संतरे ₹180 में बेचने पर एक विक्रेता को 10% की हानि होती है। 8% का लाभ पाने के लिए उसे ₹180 में कितने संतरे बेचने होंगे?","optionsHi":["33","30","32","28"],"explanationHi":"एक संतरे का विक्रय मूल्य = ₹5 = 0.9 × क्रय मूल्य, अतः क्रय मूल्य = ₹50/9। 8% लाभ के लिए विक्रय मूल्य = 1.08 × 50/9 = ₹6, अतः उसे 180 ÷ 6 = 30 संतरे बेचने होंगे।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-45","question":"After two successive discounts of 10% each, an article sells for ₹4,050. What is its marked price?","options":["₹5,200","₹4,900","₹5,000","₹5,062.50"],"answer":2,"explanation":"Two 10% discounts leave 0.9 × 0.9 = 0.81 of the MP, so MP = 4,050 ÷ 0.81 = ₹5,000. Treating them as one 20% discount gives ₹5,062.50.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"10%-10% की दो क्रमिक छूटों के बाद एक वस्तु ₹4,050 में बिकती है। उसका अंकित मूल्य क्या है?","optionsHi":["₹5,200","₹4,900","₹5,000","₹5,062.50"],"explanationHi":"दो 10% छूटों के बाद अंकित मूल्य का 0.9 × 0.9 = 0.81 बचता है, अतः अंकित मूल्य = 4,050 ÷ 0.81 = ₹5,000। इन्हें एक 20% छूट मानने पर ₹5,062.50 आता है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-46","question":"The profit made by selling an article for ₹920 is three times the loss incurred by selling it for ₹680. What is its cost price?","options":["₹740","₹800","₹760","₹720"],"answer":0,"explanation":"920 − C = 3(C − 680) gives 920 + 2,040 = 4C, so C = ₹740. Check: profit 180 = 3 × loss 60. ₹800 is the midpoint, which would need equal profit and loss.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी वस्तु को ₹920 में बेचने पर होने वाला लाभ, उसे ₹680 में बेचने पर होने वाली हानि का तीन गुना है। उसका क्रय मूल्य क्या है?","optionsHi":["₹740","₹800","₹760","₹720"],"explanationHi":"920 − C = 3(C − 680) से 920 + 2,040 = 4C, अतः C = ₹740। जाँच: लाभ 180 = 3 × हानि 60। ₹800 मध्य बिंदु है, जिसके लिए लाभ और हानि बराबर होने चाहिए।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-47","question":"A man buys a TV and a fridge for ₹60,000 in all. He sells the TV at a 10% profit and the fridge at a 20% profit, earning ₹8,400 in all. What did the fridge cost?","options":["₹24,000","₹36,000","₹28,000","₹30,000"],"answer":0,"explanation":"0.1T + 0.2(60,000 − T) = 8,400 gives 12,000 − 0.1T = 8,400, so T = ₹36,000 and the fridge cost ₹24,000. ₹36,000 is the TV's price.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक व्यक्ति एक टीवी और एक फ्रिज कुल ₹60,000 में खरीदता है। वह टीवी को 10% लाभ पर और फ्रिज को 20% लाभ पर बेचता है, और कुल ₹8,400 कमाता है। फ्रिज की कीमत क्या थी?","optionsHi":["₹24,000","₹36,000","₹28,000","₹30,000"],"explanationHi":"0.1T + 0.2(60,000 − T) = 8,400 से 12,000 − 0.1T = 8,400, अतः T = ₹36,000 और फ्रिज की कीमत ₹24,000 थी। ₹36,000 टीवी की कीमत है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-48","question":"Two successive discounts of x% and 20% are equivalent to a single discount of 32%. What is x?","options":["12","15","10","12.5"],"answer":1,"explanation":"(1 − x/100) × 0.8 = 0.68, so 1 − x/100 = 0.85 and x = 15. Subtracting 32 − 20 = 12 ignores that the second discount is on a reduced price.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"x% और 20% की दो क्रमिक छूटें 32% की एकल छूट के समतुल्य हैं। x क्या है?","optionsHi":["12","15","10","12.5"],"explanationHi":"(1 − x/100) × 0.8 = 0.68, अतः 1 − x/100 = 0.85 और x = 15। 32 − 20 = 12 घटाना इस बात को अनदेखा करता है कि दूसरी छूट घटे हुए मूल्य पर लगती है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-49","question":"The cost price of 15 articles equals the marked price of 12 articles. If a discount of 10% is allowed, what is the profit percent?","options":["15%","25%","10%","12.5%"],"answer":3,"explanation":"MP = 15/12 × CP = 1.25 CP; SP = 0.9 × 1.25 = 1.125 CP, so profit = 12.5%. 25% is the markup before the discount.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"15 वस्तुओं का क्रय मूल्य 12 वस्तुओं के अंकित मूल्य के बराबर है। यदि 10% की छूट दी जाए, तो लाभ प्रतिशत क्या है?","optionsHi":["15%","25%","10%","12.5%"],"explanationHi":"अंकित मूल्य = 15/12 × क्रय मूल्य = 1.25 क्रय मूल्य; विक्रय मूल्य = 0.9 × 1.25 = 1.125 क्रय मूल्य, अतः लाभ = 12.5%। 25% छूट से पहले की अंकन वृद्धि है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-50","question":"A merchant buys goods for ₹25,000. He sells one-fourth of them at a 10% loss. At what profit percent must he sell the rest to gain 20% on the whole?","options":["33 1/3%","30%","25%","26 2/3%"],"answer":1,"explanation":"Weighted: 0.25 × (−10) + 0.75p = 20, so 0.75p = 22.5 and p = 30%. In money: he needs ₹30,000, gets ₹5,625 from the first part, so ₹24,375 from ₹18,750 of goods, which is 30% profit.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक व्यापारी ₹25,000 का माल खरीदता है। वह उसका एक-चौथाई 10% हानि पर बेचता है। पूरे माल पर 20% का लाभ पाने के लिए उसे शेष को कितने प्रतिशत लाभ पर बेचना चाहिए?","optionsHi":["33 1/3%","30%","25%","26 2/3%"],"explanationHi":"भारित: 0.25 × (−10) + 0.75p = 20, अतः 0.75p = 22.5 और p = 30%। धन में: उसे ₹30,000 चाहिए, पहले भाग से ₹5,625 मिलते हैं, अतः ₹18,750 के माल से ₹24,375 चाहिए, जो 30% लाभ है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-51","question":"A shopkeeper gains 20% after allowing a 25% discount on the marked price. What would his profit percent be if he allowed only a 15% discount?","options":["32%","30%","34%","36%"],"answer":3,"explanation":"MP/CP = 1.2/0.75 = 1.6. With a 15% discount SP = 0.85 × 1.6 = 1.36 CP, a 36% profit. Adding the 10-point smaller discount to 20% (30%) ignores that it is 10% of the MP, not of the CP.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"अंकित मूल्य पर 25% की छूट देने के बाद एक दुकानदार को 20% का लाभ होता है। यदि वह केवल 15% की छूट देता तो उसका लाभ प्रतिशत क्या होता?","optionsHi":["32%","30%","34%","36%"],"explanationHi":"अंकित मूल्य/क्रय मूल्य = 1.2/0.75 = 1.6। 15% छूट पर विक्रय मूल्य = 0.85 × 1.6 = 1.36 क्रय मूल्य, अर्थात् 36% लाभ। 10 अंक कम छूट को 20% में जोड़ना (30%) इस बात को अनदेखा करता है कि वह अंकित मूल्य का 10% है, क्रय मूल्य का नहीं।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-52","question":"A shopkeeper sells an article at a profit of 25%. If his cost price rises by 20% and he keeps the same selling price, what is his new profit percent?","options":["5%","6 1/4%","4%","4 1/6%"],"answer":3,"explanation":"Take CP = 100 and SP = 125. New CP = 120, profit = 5, so profit % = 5/120 × 100 = 4 1/6%. Subtracting 25 − 20 = 5% ignores the larger base.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक दुकानदार किसी वस्तु को 25% लाभ पर बेचता है। यदि उसका क्रय मूल्य 20% बढ़ जाए और वह वही विक्रय मूल्य रखे, तो उसका नया लाभ प्रतिशत क्या होगा?","optionsHi":["5%","6 1/4%","4%","4 1/6%"],"explanationHi":"क्रय मूल्य = 100 और विक्रय मूल्य = 125 लें। नया क्रय मूल्य = 120, लाभ = 5, अतः लाभ % = 5/120 × 100 = 4 1/6%। 25 − 20 = 5% घटाना बड़े आधार को अनदेखा करता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-53","question":"A shopkeeper gives a discount equal to the profit he makes, and the discount is 20% of the marked price. What is his profit percent?","options":["33 1/3%","40%","20%","25%"],"answer":0,"explanation":"Take MP = 100: discount = 20, SP = 80 and profit = 20, so CP = 60 and profit % = 20/60 = 33 1/3%.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार अपने लाभ के बराबर छूट देता है, और वह छूट अंकित मूल्य का 20% है। उसका लाभ प्रतिशत क्या है?","optionsHi":["33 1/3%","40%","20%","25%"],"explanationHi":"अंकित मूल्य = 100 लें: छूट = 20, विक्रय मूल्य = 80 और लाभ = 20, अतः क्रय मूल्य = 60 और लाभ % = 20/60 = 33 1/3%।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-54","question":"A man buys a used car for ₹3,60,000, spends ₹40,000 on repairs and sells it for ₹4,50,000 through a broker who charges 4% commission on the selling price. What is his profit percent?","options":["12.5%","7.5%","10%","8%"],"answer":3,"explanation":"Total cost = ₹4,00,000. He receives 4,50,000 − 18,000 = ₹4,32,000, so profit = ₹32,000 = 8%. 12.5% forgets the commission.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"एक व्यक्ति एक पुरानी कार ₹3,60,000 में खरीदता है, मरम्मत पर ₹40,000 खर्च करता है और उसे एक दलाल के माध्यम से ₹4,50,000 में बेचता है, जो विक्रय मूल्य पर 4% कमीशन लेता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["12.5%","7.5%","10%","8%"],"explanationHi":"कुल लागत = ₹4,00,000। उसे 4,50,000 − 18,000 = ₹4,32,000 मिलते हैं, अतः लाभ = ₹32,000 = 8%। 12.5% में कमीशन को भुला दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-55","question":"A shopkeeper marks an article 40% above cost, allows a 15% discount and then charges 10% GST on the discounted price. The customer pays ₹1,309. What is the cost price?","options":["₹1,000","₹935","₹1,100","₹1,190"],"answer":0,"explanation":"Customer price = CP × 1.4 × 0.85 × 1.1 = 1.309 CP = ₹1,309, so CP = ₹1,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक दुकानदार किसी वस्तु को क्रय मूल्य से 40% अधिक अंकित करता है, 15% की छूट देता है और फिर छूट के बाद के मूल्य पर 10% GST लगाता है। ग्राहक ₹1,309 का भुगतान करता है। क्रय मूल्य क्या है?","optionsHi":["₹1,000","₹935","₹1,100","₹1,190"],"explanationHi":"ग्राहक का मूल्य = क्रय मूल्य × 1.4 × 0.85 × 1.1 = 1.309 क्रय मूल्य = ₹1,309, अतः क्रय मूल्य = ₹1,000।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-56","question":"A store's monthly sales are ₹8 lakh and its gross margin is 25% of sales. Fixed expenses are ₹1.2 lakh a month. What is its net profit as a percent of the cost of goods sold?","options":["25%","10%","16 2/3%","13 1/3%"],"answer":3,"explanation":"Gross profit = 25% of 8 = ₹2 lakh, so cost of goods = ₹6 lakh. Net profit = 2 − 1.2 = ₹0.8 lakh = 0.8/6 = 13 1/3% of cost. 10% divides by sales instead.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान की मासिक बिक्री ₹8 लाख है और उसका सकल मार्जिन बिक्री का 25% है। स्थिर व्यय प्रति माह ₹1.2 लाख हैं। बेचे गए माल की लागत के प्रतिशत के रूप में उसका शुद्ध लाभ कितना है?","optionsHi":["25%","10%","16 2/3%","13 1/3%"],"explanationHi":"सकल लाभ = 8 का 25% = ₹2 लाख, अतः माल की लागत = ₹6 लाख। शुद्ध लाभ = 2 − 1.2 = ₹0.8 लाख = 0.8/6 = लागत का 13 1/3%। 10% में बिक्री से भाग दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-57","question":"How many of the following statements are correct?\n1. A markup of 50% followed by a discount of 33 1/3% gives neither profit nor loss.\n2. 'Buy 2, get 1 free' is the same as a discount of 33 1/3%.\n3. Selling at cost price but using a 900 g weight for 1 kg gives a gain of 11 1/9%.\n4. A profit of 20% on the selling price equals a profit of 25% on the cost price.","options":["All four","Only one","Only three","Only two"],"answer":0,"explanation":"All four are true. 1: 1.5 × 2/3 = 1. 2: one item free in three is 1/3 off. 3: gain = 100/900 = 11 1/9%. 4: profit of 20 on SP 100 is 20/80 = 25% on cost.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. 50% की अंकन वृद्धि के बाद 33 1/3% की छूट देने पर न लाभ होता है, न हानि।\n2. '2 खरीदें, 1 मुफ़्त पाएँ' 33 1/3% की छूट के समान है।\n3. क्रय मूल्य पर बेचते हुए 1 kg के स्थान पर 900 g का बाट प्रयोग करने से 11 1/9% का लाभ होता है।\n4. विक्रय मूल्य पर 20% का लाभ, क्रय मूल्य पर 25% के लाभ के बराबर होता है।","optionsHi":["चारों","केवल एक","केवल तीन","केवल दो"],"explanationHi":"चारों सही हैं। 1: 1.5 × 2/3 = 1। 2: तीन में से एक वस्तु मुफ़्त होना 1/3 की छूट है। 3: लाभ = 100/900 = 11 1/9%। 4: विक्रय मूल्य 100 पर 20 का लाभ क्रय मूल्य पर 20/80 = 25% है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-58","question":"A shopkeeper buys three kinds of pens in the ratio 3 : 2 : 5 by number at ₹8, ₹12 and ₹16 each. He sells all of them at ₹16 each. What is his profit percent?","options":["20%","25%","33 1/3%","28%"],"answer":1,"explanation":"For 10 pens CP = 24 + 24 + 80 = ₹128 and SP = ₹160, so profit = 32/128 = 25%. Using the simple average price ₹12 gives 33 1/3%, ignoring the ratio.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकानदार तीन प्रकार के पेन संख्या में 3 : 2 : 5 के अनुपात में क्रमशः ₹8, ₹12 और ₹16 प्रति पेन की दर से खरीदता है। वह सभी को ₹16 प्रति पेन की दर से बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","25%","33 1/3%","28%"],"explanationHi":"10 पेनों के लिए क्रय मूल्य = 24 + 24 + 80 = ₹128 और विक्रय मूल्य = ₹160, अतः लाभ = 32/128 = 25%। साधारण औसत मूल्य ₹12 लेने पर 33 1/3% आता है, जो अनुपात को अनदेखा करता है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-59","question":"A manufacturer's cost is ₹10,000 and he wants a 26% profit after paying a 10% commission on the selling price to his agent. If he allows a 12.5% discount, what should the marked price be?","options":["₹16,000","₹14,400","₹15,750","₹15,840"],"answer":0,"explanation":"He needs ₹12,600 after commission, so SP = 12,600 ÷ 0.9 = ₹14,000, and MP = 14,000 ÷ 0.875 = ₹16,000. ₹15,840 adds 10% to ₹12,600 instead of dividing by 0.9.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक निर्माता की लागत ₹10,000 है और वह अपने एजेंट को विक्रय मूल्य पर 10% कमीशन देने के बाद 26% का लाभ चाहता है। यदि वह 12.5% की छूट देता है, तो अंकित मूल्य क्या होना चाहिए?","optionsHi":["₹16,000","₹14,400","₹15,750","₹15,840"],"explanationHi":"कमीशन के बाद उसे ₹12,600 चाहिए, अतः विक्रय मूल्य = 12,600 ÷ 0.9 = ₹14,000, और अंकित मूल्य = 14,000 ÷ 0.875 = ₹16,000। ₹15,840 में 0.9 से भाग देने के बजाय ₹12,600 में 10% जोड़ा गया है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-60","question":"A man gains 25% on one article and loses 20% on another, and overall makes neither profit nor loss. If the two selling prices differ by ₹1,000, what was the total cost of the two articles?","options":["₹9,000","₹10,000","₹4,500","₹8,000"],"answer":0,"explanation":"0.25a = 0.2b gives a : b = 4 : 5; take a = 4k, b = 5k. SPs are 1.25 × 4k = 5k and 0.8 × 5k = 4k, which differ by k = 1,000. Total cost = 9k = ₹9,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यक्ति एक वस्तु पर 25% लाभ और दूसरी पर 20% हानि कमाता है, और कुल मिलाकर न लाभ होता है, न हानि। यदि दोनों विक्रय मूल्यों का अंतर ₹1,000 है, तो दोनों वस्तुओं की कुल लागत क्या थी?","optionsHi":["₹9,000","₹10,000","₹4,500","₹8,000"],"explanationHi":"0.25a = 0.2b से a : b = 4 : 5; a = 4k, b = 5k लें। विक्रय मूल्य 1.25 × 4k = 5k और 0.8 × 5k = 4k हैं, जिनका अंतर k = 1,000 है। कुल लागत = 9k = ₹9,000।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-61","question":"A shop sells 400 units a day at ₹50 each; each unit costs it ₹40. When the price is cut by 10%, daily sales rise by 50%. What happens to the shop's daily profit?","options":["It rises by 12.5%","It falls by 10%","It falls by 25%","It rises by 35%"],"answer":2,"explanation":"Before: 400 × (50 − 40) = ₹4,000. After: 600 × (45 − 40) = ₹3,000, a 25% fall. Revenue rises 35% (₹20,000 → ₹27,000), which is the trap.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान प्रतिदिन ₹50 प्रति इकाई की दर से 400 इकाइयाँ बेचती है; प्रत्येक इकाई की उसे लागत ₹40 है। जब मूल्य 10% घटा दिया जाता है, तो दैनिक बिक्री 50% बढ़ जाती है। दुकान के दैनिक लाभ का क्या होता है?","optionsHi":["12.5% की वृद्धि","10% की कमी","25% की कमी","35% की वृद्धि"],"explanationHi":"पहले: 400 × (50 − 40) = ₹4,000। बाद में: 600 × (45 − 40) = ₹3,000, यानी 25% की कमी। राजस्व 35% बढ़ता है (₹20,000 → ₹27,000), जो जाल है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-62","question":"The cost of making an article is split among material, labour and overheads in the ratio 4 : 3 : 1, and it is sold at a 50% profit. Material cost rises by 25% and labour by 20%, overheads unchanged. If the selling price stays the same, what is the new profit percent?","options":["25%","20%","30%","27.5%"],"answer":0,"explanation":"Take cost = 8 (4 + 3 + 1) and SP = 12. New cost = 5 + 3.6 + 1 = 9.6, so profit = 2.4/9.6 = 25%. Subtracting the 20% cost rise from 50% gives 30%, a percent-of-different-bases slip.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी वस्तु को बनाने की लागत सामग्री, श्रम और उपरिव्यय में 4 : 3 : 1 के अनुपात में बँटी है, और वह 50% लाभ पर बेची जाती है। सामग्री की लागत 25% और श्रम की लागत 20% बढ़ जाती है, उपरिव्यय अपरिवर्तित रहता है। यदि विक्रय मूल्य वही रहता है, तो नया लाभ प्रतिशत क्या है?","optionsHi":["25%","20%","30%","27.5%"],"explanationHi":"लागत = 8 (4 + 3 + 1) और विक्रय मूल्य = 12 लें। नई लागत = 5 + 3.6 + 1 = 9.6, अतः लाभ = 2.4/9.6 = 25%। 50% में से 20% की लागत वृद्धि घटाने पर 30% आता है, जो अलग-अलग आधारों के प्रतिशत की भूल है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-63","question":"A sells an article to B at a profit of x%, and B sells it to C at a profit of 2x%. A's cost was ₹1,200 and C paid ₹2,016. What is x?","options":["22.5","25","15","20"],"answer":3,"explanation":"(1 + x/100)(1 + 2x/100) = 2,016/1,200 = 1.68. Trying x = 20: 1.2 × 1.4 = 1.68, so x = 20 (the other root is negative).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A एक वस्तु B को x% लाभ पर बेचता है, और B उसे C को 2x% लाभ पर बेचता है। A की लागत ₹1,200 थी और C ने ₹2,016 दिए। x क्या है?","optionsHi":["22.5","25","15","20"],"explanationHi":"(1 + x/100)(1 + 2x/100) = 2,016/1,200 = 1.68। x = 20 आज़माएँ: 1.2 × 1.4 = 1.68, अतः x = 20 (दूसरा मूल ऋणात्मक है)।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-64","question":"Assertion (A): A trader who marks his goods 25% above cost and allows a 20% discount makes neither profit nor loss.\nReason (R): Successive changes of +a% and −b% give a net change of (a − b − ab/100)%.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"By R: 25 − 20 − (25 × 20)/100 = 0, so A is true and follows from R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): जो व्यापारी अपना माल क्रय मूल्य से 25% अधिक अंकित करता है और 20% की छूट देता है, उसे न लाभ होता है, न हानि।\nकारण (R): +a% और −b% के क्रमिक परिवर्तनों से कुल परिवर्तन (a − b − ab/100)% होता है।","optionsHi":["A सही है लेकिन R गलत है","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A गलत है लेकिन R सही है"],"explanationHi":"R के अनुसार: 25 − 20 − (25 × 20)/100 = 0, अतः A सही है और R से ही निकलता है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-65","question":"A man buys some oranges at 6 for ₹5 and an equal number at 4 for ₹5. He sells all of them at 5 for ₹5. What is his gain or loss percent?","options":["4 1/6% loss","No profit no loss","4% loss","4% gain"],"answer":2,"explanation":"Average CP per orange = (5/6 + 5/4)/2 = 25/24 rupee; SP = ₹1, so loss = (1/24)/(25/24) = 1/25 = 4%. Averaging the rates 6 and 4 to get 5 per ₹5 is the trap; 4 1/6% divides the loss by the SP.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यक्ति कुछ संतरे ₹5 के 6 की दर से और उतने ही संतरे ₹5 के 4 की दर से खरीदता है। वह सभी को ₹5 के 5 की दर से बेचता है। उसका लाभ या हानि प्रतिशत क्या है?","optionsHi":["4 1/6% हानि","न लाभ न हानि","4% हानि","4% लाभ"],"explanationHi":"प्रति संतरा औसत क्रय मूल्य = (5/6 + 5/4)/2 = 25/24 रुपये; विक्रय मूल्य = ₹1, अतः हानि = (1/24)/(25/24) = 1/25 = 4%। दरों 6 और 4 का औसत लेकर ₹5 में 5 मान लेना जाल है; 4 1/6% में हानि को विक्रय मूल्य से भाग दिया गया है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-66","question":"The cost prices of two articles are in the ratio 3 : 5. The first is sold at a 20% profit. At what profit or loss percent must the second be sold so that the overall profit is 5%?","options":["4% loss","4% profit","5% loss","2.5% loss"],"answer":0,"explanation":"Take CPs 3 and 5: total profit needed = 0.05 × 8 = 0.4, the first gives 0.6, so the second must lose 0.2 on 5, i.e. 4% loss.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"दो वस्तुओं के क्रय मूल्य 3 : 5 के अनुपात में हैं। पहली को 20% लाभ पर बेचा जाता है। दूसरी को कितने प्रतिशत लाभ या हानि पर बेचा जाए ताकि कुल लाभ 5% हो?","optionsHi":["4% हानि","4% लाभ","5% हानि","2.5% हानि"],"explanationHi":"क्रय मूल्य 3 और 5 लें: कुल आवश्यक लाभ = 0.05 × 8 = 0.4, पहली से 0.6 मिलता है, अतः दूसरी पर 5 में से 0.2 की हानि होनी चाहिए, यानी 4% हानि।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-67","question":"A shop offers two schemes on an item marked ₹1,000. Scheme 1: 30% off. Scheme 2: buy 3 get 1 free, plus 5% off the bill. For a customer who needs exactly 4 items, which scheme is cheaper and by how much?","options":["Scheme 2, by ₹50","Scheme 1, by ₹150","Scheme 1, by ₹50","Both cost the same"],"answer":2,"explanation":"Scheme 1: 4 × 700 = ₹2,800. Scheme 2: pay for 3 at 5% off = 3,000 × 0.95 = ₹2,850. Scheme 1 is cheaper by ₹50 (scheme 2 is an effective 28.75% discount).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान ₹1,000 अंकित मूल्य वाली एक वस्तु पर दो योजनाएँ देती है। योजना 1: 30% की छूट। योजना 2: 3 खरीदें 1 मुफ़्त पाएँ, साथ में बिल पर 5% की छूट। ठीक 4 वस्तुएँ चाहने वाले ग्राहक के लिए कौन-सी योजना सस्ती है और कितनी?","optionsHi":["योजना 2, ₹50 से","योजना 1, ₹150 से","योजना 1, ₹50 से","दोनों का मूल्य समान है"],"explanationHi":"योजना 1: 4 × 700 = ₹2,800। योजना 2: 3 का भुगतान 5% छूट पर = 3,000 × 0.95 = ₹2,850। योजना 1 ₹50 सस्ती है (योजना 2 प्रभावी रूप से 28.75% की छूट है)।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-68","question":"A businessman buys a machine for ₹2,00,000. It earns him a net ₹30,000 a year for 3 years, after which he sells it at 30% below its cost price. What is his overall gain percent on the investment?","options":["30%","15%","10%","45%"],"answer":1,"explanation":"Total received = 3 × 30,000 + 0.7 × 2,00,000 = 90,000 + 1,40,000 = ₹2,30,000, a gain of ₹30,000 = 15%. 45% ignores the loss on resale.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक व्यवसायी ₹2,00,000 में एक मशीन खरीदता है। यह उसे 3 वर्ष तक प्रति वर्ष शुद्ध ₹30,000 कमाकर देती है, जिसके बाद वह इसे इसके क्रय मूल्य से 30% कम पर बेच देता है। निवेश पर उसका कुल लाभ प्रतिशत क्या है?","optionsHi":["30%","15%","10%","45%"],"explanationHi":"कुल प्राप्ति = 3 × 30,000 + 0.7 × 2,00,000 = 90,000 + 1,40,000 = ₹2,30,000, यानी ₹30,000 का लाभ = 15%। 45% में पुनर्विक्रय की हानि को अनदेखा किया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-69","question":"A mobile cover bought for ₹150 is sold for ₹186. What is the profit percent?","options":["36%","24%","19.35%","20%"],"answer":1,"explanation":"Profit = ₹36 on a cost of ₹150: 36/150 × 100 = 24%. Dividing by the selling price gives 19.35%.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹150 में खरीदा गया एक मोबाइल कवर ₹186 में बेचा जाता है। लाभ प्रतिशत क्या है?","optionsHi":["36%","24%","19.35%","20%"],"explanationHi":"₹150 के क्रय मूल्य पर लाभ ₹36 है: 36/150 × 100 = 24%। विक्रय मूल्य से भाग देने पर 19.35% आता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-70","question":"An article costing ₹2,400 is sold at a loss of 15%. What is its selling price?","options":["₹2,040","₹2,760","₹2,085","₹2,000"],"answer":0,"explanation":"SP = 85% of 2,400 = ₹2,040. ₹2,760 adds 15% as if it were a profit, and ₹2,000 rounds the loss to ₹400.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"₹2,400 की लागत वाली एक वस्तु 15% की हानि पर बेची जाती है। उसका विक्रय मूल्य क्या है?","optionsHi":["₹2,040","₹2,760","₹2,085","₹2,000"],"explanationHi":"विक्रय मूल्य = 2,400 का 85% = ₹2,040। ₹2,760 में 15% को लाभ की तरह जोड़ दिया गया है, और ₹2,000 में हानि को ₹400 मान लिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-71","question":"A farmer's cost of growing wheat is ₹1,940 per quintal and he sells it to the government at an MSP of ₹2,425 per quintal. What is his profit percent?","options":["20%","22.5%","48.5%","25%"],"answer":3,"explanation":"Profit = 485 on 1,940 = 25% (1,940 × 1.25 = 2,425). 485/2,425 = 20% wrongly takes profit on SP.","difficulty":"easy","source":"RRB NTPC · State PSC","questionHi":"एक किसान की गेहूँ उगाने की लागत ₹1,940 प्रति क्विंटल है और वह उसे सरकार को ₹2,425 प्रति क्विंटल के न्यूनतम समर्थन मूल्य (MSP) पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","22.5%","48.5%","25%"],"explanationHi":"लाभ = 1,940 पर 485 = 25% (1,940 × 1.25 = 2,425)। 485/2,425 = 20% में गलती से लाभ विक्रय मूल्य पर लिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-72","question":"On a phone with MRP ₹12,000, a store gives a 10% discount and the bank then gives 5% cashback on the amount paid. What is the effective discount on the MRP?","options":["15%","14%","14.5%","15.5%"],"answer":2,"explanation":"Net price = 0.9 × 0.95 = 0.855 of MRP, an effective discount of 14.5%. Successive discounts: 10 + 5 − (10 × 5)/100 = 14.5%.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"₹12,000 के MRP वाले एक फोन पर एक दुकान 10% की छूट देती है और फिर बैंक चुकाई गई राशि पर 5% कैशबैक देता है। MRP पर प्रभावी छूट क्या है?","optionsHi":["15%","14%","14.5%","15.5%"],"explanationHi":"शुद्ध मूल्य = MRP का 0.9 × 0.95 = 0.855, यानी 14.5% की प्रभावी छूट। क्रमिक छूट: 10 + 5 − (10 × 5)/100 = 14.5%।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-73","question":"A shopkeeper sells a pressure cooker for ₹2,016, which includes 12% GST, and makes a profit of 20% on his cost. What is his cost price?","options":["₹1,680","₹1,600","₹1,500","₹1,440"],"answer":2,"explanation":"Price before GST = 2,016 ÷ 1.12 = ₹1,800. Cost = 1,800 ÷ 1.2 = ₹1,500. GST is not part of the seller's profit.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"एक दुकानदार एक प्रेशर कुकर ₹2,016 में बेचता है, जिसमें 12% GST शामिल है, और अपनी लागत पर 20% का लाभ कमाता है। उसका क्रय मूल्य क्या है?","optionsHi":["₹1,680","₹1,600","₹1,500","₹1,440"],"explanationHi":"GST से पहले का मूल्य = 2,016 ÷ 1.12 = ₹1,800। क्रय मूल्य = 1,800 ÷ 1.2 = ₹1,500। GST विक्रेता के लाभ का भाग नहीं होता।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-74","question":"A grocer mixes rice costing ₹32 per kg with rice costing ₹40 per kg in the ratio 3 : 1 and sells the mixture at ₹40.80 per kg. What is his profit percent?","options":["2%","20%","13.33%","25%"],"answer":1,"explanation":"Cost of the mix = (3 × 32 + 1 × 40)/4 = ₹34 per kg. Profit = 6.80/34 = 20%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक किराना व्यापारी ₹32 प्रति kg वाले चावल को ₹40 प्रति kg वाले चावल के साथ 3 : 1 के अनुपात में मिलाता है और मिश्रण को ₹40.80 प्रति kg पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["2%","20%","13.33%","25%"],"explanationHi":"मिश्रण की लागत = (3 × 32 + 1 × 40)/4 = ₹34 प्रति kg। लाभ = 6.80/34 = 20%।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-75","question":"A fruit seller buys 2 dozen bananas at ₹30 a dozen and 3 dozen at ₹40 a dozen. He sells all of them at ₹4.50 each. What is his profit percent?","options":["50%","35%","28.6%","45%"],"answer":0,"explanation":"Cost = 2 × 30 + 3 × 40 = ₹180 for 60 bananas. Sale = 60 × 4.50 = ₹270. Profit = 90/180 = 50%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक फल विक्रेता ₹30 प्रति दर्जन की दर से 2 दर्जन केले और ₹40 प्रति दर्जन की दर से 3 दर्जन केले खरीदता है। वह सभी को ₹4.50 प्रति केला बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["50%","35%","28.6%","45%"],"explanationHi":"लागत = 2 × 30 + 3 × 40 = 60 केलों के लिए ₹180। बिक्री = 60 × 4.50 = ₹270। लाभ = 90/180 = 50%।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-76","question":"A trader marks his goods 60% above cost and allows successive discounts of 25% and 10%. What is his profit percent?","options":["25%","12%","6%","8%"],"answer":3,"explanation":"SP = 1.6 × 0.75 × 0.9 = 1.08 of cost, a profit of 8%. 60 − 35 = 25% wrongly adds discounts and markup.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यापारी अपना माल क्रय मूल्य से 60% अधिक अंकित करता है और 25% और 10% की क्रमिक छूटें देता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["25%","12%","6%","8%"],"explanationHi":"विक्रय मूल्य = 1.6 × 0.75 × 0.9 = क्रय मूल्य का 1.08, यानी 8% का लाभ। 60 − 35 = 25% में छूटों और अंकन वृद्धि को गलत ढंग से जोड़ा गया है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-77","question":"A dishonest shopkeeper uses a 960 g weight in place of 1 kg and openly sells at 4% below cost price. What is his actual result?","options":["4% gain","0.16% loss","8.33% gain","No profit, no loss"],"answer":3,"explanation":"For 960 g (cost 0.96 of a kg) he charges 96% of the price of 1 kg, which is exactly the cost of 960 g. So there is neither profit nor loss.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक बेईमान दुकानदार 1 kg के स्थान पर 960 g का बाट प्रयोग करता है और खुले तौर पर क्रय मूल्य से 4% कम पर बेचता है। उसका वास्तविक परिणाम क्या है?","optionsHi":["4% लाभ","0.16% हानि","8.33% लाभ","न लाभ, न हानि"],"explanationHi":"960 g के लिए (जिसकी लागत 1 kg का 0.96 है) वह 1 kg के मूल्य का 96% लेता है, जो ठीक 960 g की लागत है। अतः न लाभ है, न हानि।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-78","question":"A retailer gets a 20% trade discount and then a 5% cash discount on the list price of goods. He sells them at the list price. What is his profit percent?","options":["25%","33.33%","31.58%","24%"],"answer":2,"explanation":"His cost = 0.8 × 0.95 = 0.76 of list price. Profit = 0.24/0.76 = 31.58%. 25% is the total discount, which is profit on SP, not on cost.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक खुदरा विक्रेता को माल के सूची मूल्य पर 20% व्यापार छूट और फिर 5% नकद छूट मिलती है। वह उसे सूची मूल्य पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["25%","33.33%","31.58%","24%"],"explanationHi":"उसका क्रय मूल्य = सूची मूल्य का 0.8 × 0.95 = 0.76। लाभ = 0.24/0.76 = 31.58%। 25% कुल छूट है, जो विक्रय मूल्य पर लाभ है, क्रय मूल्य पर नहीं।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-79","question":"A home bakery has fixed costs of ₹45,000 a month. Each cake costs ₹150 to make and is sold for ₹240. How many cakes must the bakery sell in a month to make a profit of ₹18,000?","options":["500","700","625","750"],"answer":1,"explanation":"Each cake contributes 240 − 150 = ₹90. Cakes needed = (45,000 + 18,000)/90 = 700. 500 cakes only break even.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक घरेलू बेकरी की स्थिर लागत ₹45,000 प्रति माह है। प्रत्येक केक बनाने की लागत ₹150 है और उसे ₹240 में बेचा जाता है। ₹18,000 का लाभ कमाने के लिए बेकरी को एक माह में कितने केक बेचने होंगे?","optionsHi":["500","700","625","750"],"explanationHi":"प्रत्येक केक का योगदान 240 − 150 = ₹90 है। आवश्यक केक = (45,000 + 18,000)/90 = 700। 500 केक पर केवल बराबरी (न लाभ, न हानि) होती है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-80","question":"A dealer sells a cooler to a retailer at 20% profit, and the retailer sells it at 25% profit. The customer pays ₹5,400 including 12.5% GST. What did the cooler cost the dealer?","options":["₹3,200","₹3,000","₹3,600","₹2,880"],"answer":0,"explanation":"Price before GST = 5,400 ÷ 1.125 = ₹4,800. Retailer's cost = 4,800 ÷ 1.25 = ₹3,840. Dealer's cost = 3,840 ÷ 1.2 = ₹3,200.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक डीलर एक कूलर एक खुदरा विक्रेता को 20% लाभ पर बेचता है, और खुदरा विक्रेता उसे 25% लाभ पर बेचता है। ग्राहक 12.5% GST सहित ₹5,400 देता है। डीलर को कूलर कितने में पड़ा?","optionsHi":["₹3,200","₹3,000","₹3,600","₹2,880"],"explanationHi":"GST से पहले का मूल्य = 5,400 ÷ 1.125 = ₹4,800। खुदरा विक्रेता का क्रय मूल्य = 4,800 ÷ 1.25 = ₹3,840। डीलर का क्रय मूल्य = 3,840 ÷ 1.2 = ₹3,200।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-81","question":"An article is sold at a 20% profit. If both its cost price and selling price were ₹60 more, the profit would be 15%. What is the cost price?","options":["₹180","₹240","₹200","₹150"],"answer":0,"explanation":"(1.2c + 60)/(c + 60) = 1.15 gives 1.2c + 60 = 1.15c + 69, so 0.05c = 9 and c = ₹180. Profit stays ₹36, now on ₹240 = 15%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक वस्तु 20% लाभ पर बेची जाती है। यदि उसका क्रय मूल्य और विक्रय मूल्य दोनों ₹60 अधिक होते, तो लाभ 15% होता। क्रय मूल्य क्या है?","optionsHi":["₹180","₹240","₹200","₹150"],"explanationHi":"(1.2c + 60)/(c + 60) = 1.15 से 1.2c + 60 = 1.15c + 69, अतः 0.05c = 9 और c = ₹180। लाभ ₹36 ही रहता है, जो अब ₹240 पर 15% है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-82","question":"A manufacturer sells to a wholesaler at 10% profit, the wholesaler to a retailer at 15% profit and the retailer to a customer at 20% profit. If the customer pays ₹30,360, what was the manufacturing cost?","options":["₹20,240","₹22,000","₹18,975","₹20,000"],"answer":3,"explanation":"Chain multiplier = 1.1 × 1.15 × 1.2 = 1.518. Cost = 30,360 ÷ 1.518 = ₹20,000. Adding 10 + 15 + 20 = 45% gives the wrong ₹20,938.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक निर्माता थोक विक्रेता को 10% लाभ पर, थोक विक्रेता खुदरा विक्रेता को 15% लाभ पर और खुदरा विक्रेता ग्राहक को 20% लाभ पर बेचता है। यदि ग्राहक ₹30,360 देता है, तो निर्माण लागत क्या थी?","optionsHi":["₹20,240","₹22,000","₹18,975","₹20,000"],"explanationHi":"श्रृंखला गुणक = 1.1 × 1.15 × 1.2 = 1.518। लागत = 30,360 ÷ 1.518 = ₹20,000। 10 + 15 + 20 = 45% जोड़ने पर गलत ₹20,938 आता है।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-83","question":"A shopkeeper sells 3/5 of his stock at a 20% profit and the rest at a loss of x%. Overall he makes a 4% profit. What is x?","options":["16","24","20","10"],"answer":2,"explanation":"Weighted: 0.6 × 20 − 0.4x = 4, so 0.4x = 8 and x = 20. 16 subtracts 4 from 20 without weighting, and 24 adds them.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक दुकानदार अपने स्टॉक का 3/5 भाग 20% लाभ पर और शेष x% हानि पर बेचता है। कुल मिलाकर उसे 4% लाभ होता है। x क्या है?","optionsHi":["16","24","20","10"],"explanationHi":"भारित: 0.6 × 20 − 0.4x = 4, अतः 0.4x = 8 और x = 20। 16 में भार दिए बिना 20 में से 4 घटाया गया है, और 24 में उन्हें जोड़ दिया गया है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-84","question":"A trader wants a 14% profit after giving successive discounts of 10% and 5% on the marked price. By what percent above cost must he mark his goods?","options":["29%","33.33%","30%","31.5%"],"answer":1,"explanation":"MP × 0.9 × 0.95 = 1.14 × CP, so MP = 1.14/0.855 = 4/3 of CP, i.e. 33.33% above cost. Adding 14 + 15 = 29% is the trap.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक व्यापारी अंकित मूल्य पर 10% और 5% की क्रमिक छूटें देने के बाद 14% का लाभ चाहता है। उसे अपना माल क्रय मूल्य से कितने प्रतिशत अधिक अंकित करना चाहिए?","optionsHi":["29%","33.33%","30%","31.5%"],"explanationHi":"अंकित मूल्य × 0.9 × 0.95 = 1.14 × क्रय मूल्य, अतः अंकित मूल्य = 1.14/0.855 = क्रय मूल्य का 4/3, अर्थात् क्रय मूल्य से 33.33% अधिक। 14 + 15 = 29% जोड़ना जाल है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-85","question":"A vendor buys 80 kg of tomatoes at ₹30 per kg. 10% of them get damaged and are sold at half the cost price. At what price per kg must he sell the rest to make a 25% profit overall?","options":["₹37.50","₹40","₹41.67","₹38"],"answer":1,"explanation":"Target revenue = 1.25 × 2,400 = ₹3,000. Damaged 8 kg fetch 8 × 15 = ₹120. The other 72 kg must bring ₹2,880, i.e. ₹40 per kg.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक विक्रेता ₹30 प्रति kg की दर से 80 kg टमाटर खरीदता है। उनमें से 10% खराब हो जाते हैं और क्रय मूल्य के आधे दाम पर बिकते हैं। कुल मिलाकर 25% लाभ कमाने के लिए उसे शेष टमाटर प्रति kg किस मूल्य पर बेचने होंगे?","optionsHi":["₹37.50","₹40","₹41.67","₹38"],"explanationHi":"लक्षित राजस्व = 1.25 × 2,400 = ₹3,000। खराब 8 kg से 8 × 15 = ₹120 मिलते हैं। शेष 72 kg से ₹2,880 आने चाहिए, अर्थात् ₹40 प्रति kg।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-86","question":"Ravi buys a cycle for ₹5,000 and sells it to Mohan at a 10% profit. Later Mohan sells it back to Ravi at a 10% loss. What is Ravi's overall gain?","options":["₹550","₹500","₹0","₹50"],"answer":0,"explanation":"Ravi receives ₹5,500 and later pays 90% of 5,500 = ₹4,950, keeping the cycle. His gain = 5,500 − 4,950 = ₹550.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"रवि ₹5,000 में एक साइकिल खरीदता है और उसे मोहन को 10% लाभ पर बेचता है। बाद में मोहन उसे रवि को 10% हानि पर वापस बेच देता है। रवि का कुल लाभ कितना है?","optionsHi":["₹550","₹500","₹0","₹50"],"explanationHi":"रवि को ₹5,500 मिलते हैं और बाद में वह 5,500 का 90% = ₹4,950 देता है, और साइकिल उसके पास रहती है। उसका लाभ = 5,500 − 4,950 = ₹550।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-87","question":"On every purchase of 15 notebooks, a shop gives a discount equal to the marked price of 3 notebooks and still makes a 12% profit. By what percent above cost are the notebooks marked?","options":["32%","35%","30%","40%"],"answer":3,"explanation":"The discount is 3/15 = 20% of the marked price. 0.8 × MP = 1.12 × CP gives MP = 1.4 × CP, i.e. 40% above cost.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"हर 15 कॉपियाँ खरीदने पर एक दुकान 3 कॉपियों के अंकित मूल्य के बराबर छूट देती है और फिर भी 12% का लाभ कमाती है। कॉपियाँ क्रय मूल्य से कितने प्रतिशत अधिक अंकित हैं?","optionsHi":["32%","35%","30%","40%"],"explanationHi":"छूट अंकित मूल्य का 3/15 = 20% है। 0.8 × अंकित मूल्य = 1.12 × क्रय मूल्य से अंकित मूल्य = 1.4 × क्रय मूल्य, अर्थात् क्रय मूल्य से 40% अधिक।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-88","question":"An online seller buys a product for ₹500. The platform keeps 20% of the selling price as fee, and the seller also pays ₹50 for delivery. At what price must he list it to earn 30% profit on his cost?","options":["₹830","₹812.50","₹875","₹840"],"answer":2,"explanation":"He must keep 650 + 50 = ₹700 after the fee, which is 80% of the price. Price = 700 ÷ 0.8 = ₹875.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक ऑनलाइन विक्रेता किसी उत्पाद को ₹500 में खरीदता है। प्लेटफ़ॉर्म विक्रय मूल्य का 20% शुल्क के रूप में रखता है, और विक्रेता डिलीवरी के लिए ₹50 भी देता है। अपनी लागत पर 30% लाभ कमाने के लिए उसे इसे किस मूल्य पर सूचीबद्ध करना होगा?","optionsHi":["₹830","₹812.50","₹875","₹840"],"explanationHi":"शुल्क के बाद उसके पास 650 + 50 = ₹700 बचने चाहिए, जो मूल्य का 80% है। मूल्य = 700 ÷ 0.8 = ₹875।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-89","question":"A shopkeeper buys 120 pens for the marked price of 100 pens and sells them at a 1% discount on the marked price. What is his profit percent?","options":["20%","19%","18.8%","17.6%"],"answer":2,"explanation":"Cost of each pen = 100/120 of MP; selling price = 0.99 MP. Profit = 0.99 × 1.2 − 1 = 0.188, i.e. 18.8%.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार 100 पेनों के अंकित मूल्य पर 120 पेन खरीदता है और उन्हें अंकित मूल्य पर 1% की छूट देकर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","19%","18.8%","17.6%"],"explanationHi":"प्रत्येक पेन का क्रय मूल्य = अंकित मूल्य का 100/120; विक्रय मूल्य = 0.99 अंकित मूल्य। लाभ = 0.99 × 1.2 − 1 = 0.188, यानी 18.8%।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-90","question":"A wholesaler gives 'buy 5, get 1 free' to a retailer at the marked price. The retailer sells to customers at the same marked price with 'buy 3, get 1 free'. What is the retailer's result?","options":["8.33% loss","10% loss","No profit, no loss","10% gain"],"answer":1,"explanation":"Cost per item = 5/6 of MP; revenue per item = 3/4 of MP. Loss = (5/6 − 3/4) ÷ 5/6 = (1/12) × (6/5) = 10%.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक थोक विक्रेता खुदरा विक्रेता को अंकित मूल्य पर '5 खरीदें, 1 मुफ़्त पाएँ' देता है। खुदरा विक्रेता ग्राहकों को उसी अंकित मूल्य पर '3 खरीदें, 1 मुफ़्त पाएँ' के साथ बेचता है। खुदरा विक्रेता का परिणाम क्या है?","optionsHi":["8.33% हानि","10% हानि","न लाभ, न हानि","10% लाभ"],"explanationHi":"प्रति वस्तु क्रय मूल्य = अंकित मूल्य का 5/6; प्रति वस्तु राजस्व = अंकित मूल्य का 3/4। हानि = (5/6 − 3/4) ÷ 5/6 = (1/12) × (6/5) = 10%।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-91","question":"A sells goods to B at a 25% profit. B spends 5% of his purchase price on transport and sells to C at a 20% profit on his total cost. If C pays ₹3,150, what did the goods cost A?","options":["₹2,000","₹2,100","₹1,890","₹2,250"],"answer":0,"explanation":"Multiplier = 1.25 × 1.05 × 1.2 = 1.575. A's cost = 3,150 ÷ 1.575 = ₹2,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A माल B को 25% लाभ पर बेचता है। B अपने क्रय मूल्य का 5% परिवहन पर खर्च करता है और अपनी कुल लागत पर 20% लाभ लेकर C को बेचता है। यदि C ₹3,150 देता है, तो A को माल कितने में पड़ा?","optionsHi":["₹2,000","₹2,100","₹1,890","₹2,250"],"explanationHi":"गुणक = 1.25 × 1.05 × 1.2 = 1.575। A का क्रय मूल्य = 3,150 ÷ 1.575 = ₹2,000।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-92","question":"In a factory, raw material makes up 60% of the cost of a product and labour the remaining 40%. Raw material prices rise by 25% and wages by 10%. By what percent must the selling price rise to keep the same profit percent?","options":["17.5%","35%","20%","19%"],"answer":3,"explanation":"New cost = 0.6 × 1.25 + 0.4 × 1.10 = 1.19 of the old. The same profit percent needs the SP to rise by 19% too. 17.5% averages the rises without weights.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक कारखाने में किसी उत्पाद की लागत का 60% कच्चा माल और शेष 40% श्रम है। कच्चे माल के दाम 25% और मज़दूरी 10% बढ़ जाती है। समान लाभ प्रतिशत बनाए रखने के लिए विक्रय मूल्य कितने प्रतिशत बढ़ना चाहिए?","optionsHi":["17.5%","35%","20%","19%"],"explanationHi":"नई लागत = पुरानी का 0.6 × 1.25 + 0.4 × 1.10 = 1.19। समान लाभ प्रतिशत के लिए विक्रय मूल्य भी 19% बढ़ना चाहिए। 17.5% में वृद्धियों का बिना भार दिए औसत लिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-93","question":"A shopkeeper earns a profit of 20% on the selling price when he gives a 20% discount on the marked price. What would his profit percent on cost be if he sold at the marked price?","options":["50%","40%","45%","56.25%"],"answer":3,"explanation":"Take MP = 100: SP = 80 and cost = 80 − 20% of 80 = 64. At MP, profit = 36/64 = 56.25%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"जब एक दुकानदार अंकित मूल्य पर 20% की छूट देता है, तो उसे विक्रय मूल्य पर 20% का लाभ होता है। यदि वह अंकित मूल्य पर बेचता, तो क्रय मूल्य पर उसका लाभ प्रतिशत क्या होता?","optionsHi":["50%","40%","45%","56.25%"],"explanationHi":"अंकित मूल्य = 100 लें: विक्रय मूल्य = 80 और क्रय मूल्य = 80 − 80 का 20% = 64। अंकित मूल्य पर बेचने से लाभ = 36/64 = 56.25%।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-94","question":"A sells goods to B at a 20% profit and B sells them to C at a 10% profit. Had A sold at a 30% profit and B at a 5% profit, C would have paid ₹180 more. What was A's cost price?","options":["₹3,600","₹4,500","₹4,000","₹5,000"],"answer":2,"explanation":"Multipliers: 1.2 × 1.1 = 1.32 and 1.3 × 1.05 = 1.365. The difference 0.045 of A's cost = ₹180, so the cost = ₹4,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"A माल B को 20% लाभ पर बेचता है और B उसे C को 10% लाभ पर बेचता है। यदि A 30% लाभ पर और B 5% लाभ पर बेचते, तो C को ₹180 अधिक देने पड़ते। A का क्रय मूल्य क्या था?","optionsHi":["₹3,600","₹4,500","₹4,000","₹5,000"],"explanationHi":"गुणक: 1.2 × 1.1 = 1.32 और 1.3 × 1.05 = 1.365। अंतर A के क्रय मूल्य का 0.045 = ₹180 है, अतः क्रय मूल्य = ₹4,000।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-95","question":"If the selling price of an article is doubled, the profit triples. What is the profit percent?","options":["50%","100%","200%","150%"],"answer":1,"explanation":"Let profit be S − C. Then 2S − C = 3(S − C) gives S = 2C, so profit = C, i.e. 100%. 200% confuses the selling price (2C) with the profit.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि किसी वस्तु का विक्रय मूल्य दोगुना कर दिया जाए, तो लाभ तीन गुना हो जाता है। लाभ प्रतिशत क्या है?","optionsHi":["50%","100%","200%","150%"],"explanationHi":"माना लाभ S − C है। तब 2S − C = 3(S − C) से S = 2C, अतः लाभ = C, अर्थात् 100%। 200% में विक्रय मूल्य (2C) को लाभ समझ लिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-96","question":"A jacket marked ₹1,500 is sold at a 12% discount. What is its selling price?","options":["₹1,320","₹1,380","₹1,180","₹1,488"],"answer":0,"explanation":"SP = 88% of 1,500 = ₹1,320. ₹1,380 subtracts 8% instead of 12%, and ₹1,488 subtracts just ₹12.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹1,500 अंकित मूल्य वाली एक जैकेट 12% की छूट पर बेची जाती है। उसका विक्रय मूल्य क्या है?","optionsHi":["₹1,320","₹1,380","₹1,180","₹1,488"],"explanationHi":"विक्रय मूल्य = 1,500 का 88% = ₹1,320। ₹1,380 में 12% के बजाय 8% घटाया गया है, और ₹1,488 में केवल ₹12 घटाए गए हैं।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-97","question":"A shoe with MRP ₹999 carries 'flat 30% off' plus 'extra 10% off on the app'. How much does an app buyer pay?","options":["₹599.40","₹639.36","₹699.30","₹629.37"],"answer":3,"explanation":"999 × 0.7 × 0.9 = 999 × 0.63 = ₹629.37. Treating it as 40% off gives ₹599.40.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"₹999 के MRP वाले एक जूते पर 'सीधे 30% की छूट' के साथ 'ऐप पर अतिरिक्त 10% की छूट' है। ऐप से खरीदने वाला कितना भुगतान करता है?","optionsHi":["₹599.40","₹639.36","₹699.30","₹629.37"],"explanationHi":"999 × 0.7 × 0.9 = 999 × 0.63 = ₹629.37। इसे 40% की छूट मानने पर ₹599.40 आता है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-98","question":"A tailor buys cloth at ₹180 per metre. A shirt uses 1.6 m of cloth and ₹120 of stitching cost. If he sells each shirt for ₹510, what is his profit percent?","options":["20%","27.5%","41.7%","25%"],"answer":3,"explanation":"Cost per shirt = 1.6 × 180 + 120 = ₹408. Profit = 102/408 = 25%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक दर्ज़ी ₹180 प्रति मीटर की दर से कपड़ा खरीदता है। एक कमीज़ में 1.6 m कपड़ा और ₹120 सिलाई की लागत लगती है। यदि वह प्रत्येक कमीज़ ₹510 में बेचता है, तो उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","27.5%","41.7%","25%"],"explanationHi":"प्रति कमीज़ लागत = 1.6 × 180 + 120 = ₹408। लाभ = 102/408 = 25%।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-99","question":"A dhaba's thali costs ₹160 to make and is priced at ₹250. On each of the 5 weekdays it gives 20% off and sells 120 thalis; on each of the 2 weekend days it charges full price and sells 200 thalis. What is its weekly profit?","options":["₹72,000","₹54,000","₹60,000","₹66,000"],"answer":2,"explanation":"Weekday margin = 200 − 160 = ₹40 on 600 thalis = ₹24,000. Weekend margin = ₹90 on 400 thalis = ₹36,000. Total ₹60,000.","difficulty":"hard","source":"IBPS PO · SBI Clerk","questionHi":"एक ढाबे की थाली बनाने में ₹160 लगते हैं और उसका मूल्य ₹250 है। सप्ताह के 5 कार्यदिवसों में से प्रत्येक दिन वह 20% की छूट देता है और 120 थालियाँ बेचता है; सप्ताहांत के 2 दिनों में से प्रत्येक दिन वह पूरा मूल्य लेता है और 200 थालियाँ बेचता है। उसका साप्ताहिक लाभ क्या है?","optionsHi":["₹72,000","₹54,000","₹60,000","₹66,000"],"explanationHi":"कार्यदिवस का मार्जिन = 200 − 160 = ₹40 प्रति थाली, 600 थालियों पर = ₹24,000। सप्ताहांत का मार्जिन = ₹90, 400 थालियों पर = ₹36,000। कुल ₹60,000।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-100","question":"Two shops sell the same item at the same marked price. Shop A gives a 30% discount, while Shop B gives successive discounts of 16% and 14%. If the item is ₹56 cheaper at Shop A, what is its marked price?","options":["₹2,800","₹2,500","₹2,240","₹2,000"],"answer":1,"explanation":"Shop B's single discount = 16 + 14 − 2.24 = 27.76%. Difference = 2.24% of MP = ₹56, so MP = ₹2,500.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"दो दुकानें एक ही वस्तु उसी अंकित मूल्य पर बेचती हैं। दुकान A 30% की छूट देती है, जबकि दुकान B 16% और 14% की क्रमिक छूटें देती है। यदि वस्तु दुकान A पर ₹56 सस्ती है, तो उसका अंकित मूल्य क्या है?","optionsHi":["₹2,800","₹2,500","₹2,240","₹2,000"],"explanationHi":"दुकान B की एकल छूट = 16 + 14 − 2.24 = 27.76%। अंतर = अंकित मूल्य का 2.24% = ₹56, अतः अंकित मूल्य = ₹2,500।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-101","question":"A dealer buys two machines for ₹25,000 in all. He sells the first at a 15% profit and the second at a 25% profit, earning ₹4,750 in total profit. What did the first machine cost?","options":["₹15,000","₹10,000","₹12,500","₹17,500"],"answer":0,"explanation":"Overall profit = 4,750/25,000 = 19%. Alligation: (25 − 19) : (19 − 15) = 6 : 4 = 3 : 2. First machine = 3/5 × 25,000 = ₹15,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी कुल ₹25,000 में दो मशीनें खरीदता है। वह पहली को 15% लाभ पर और दूसरी को 25% लाभ पर बेचता है, और कुल ₹4,750 का लाभ कमाता है। पहली मशीन की कीमत क्या थी?","optionsHi":["₹15,000","₹10,000","₹12,500","₹17,500"],"explanationHi":"कुल लाभ = 4,750/25,000 = 19%। एलीगेशन: (25 − 19) : (19 − 15) = 6 : 4 = 3 : 2। पहली मशीन = 3/5 × 25,000 = ₹15,000।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-102","question":"If an article is sold at a profit of 37.5%, what is the ratio of its selling price to its cost price?","options":["11 : 8","8 : 11","3 : 8","5 : 8"],"answer":0,"explanation":"37.5% = 3/8, so SP = CP × (1 + 3/8) = 11/8 of CP. SP : CP = 11 : 8.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"यदि किसी वस्तु को 37.5% लाभ पर बेचा जाए, तो उसके विक्रय मूल्य और क्रय मूल्य का अनुपात क्या है?","optionsHi":["11 : 8","8 : 11","3 : 8","5 : 8"],"explanationHi":"37.5% = 3/8, अतः विक्रय मूल्य = क्रय मूल्य × (1 + 3/8) = क्रय मूल्य का 11/8। विक्रय मूल्य : क्रय मूल्य = 11 : 8।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-103","question":"A trader makes a profit of 25% on the selling price by selling an article for ₹1,600. At what price should he sell it to make a 20% profit on cost?","options":["₹1,536","₹1,600","₹1,500","₹1,440"],"answer":3,"explanation":"Cost = 75% of 1,600 = ₹1,200. For 20% on cost, SP = 1,200 × 1.2 = ₹1,440.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यापारी किसी वस्तु को ₹1,600 में बेचकर विक्रय मूल्य पर 25% का लाभ कमाता है। क्रय मूल्य पर 20% लाभ कमाने के लिए उसे इसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹1,536","₹1,600","₹1,500","₹1,440"],"explanationHi":"क्रय मूल्य = 1,600 का 75% = ₹1,200। क्रय मूल्य पर 20% के लिए विक्रय मूल्य = 1,200 × 1.2 = ₹1,440।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-104","question":"An electronics dealer buys at 12.5% below MRP and sells at 4% below MRP. What is his profit percent, approximately?","options":["8.5%","12.5%","9.7%","8.9%"],"answer":2,"explanation":"Profit = 0.96/0.875 − 1 = 0.0971, about 9.7%. 12.5 − 4 = 8.5% is profit as a share of MRP, not of cost.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक इलेक्ट्रॉनिक्स डीलर MRP से 12.5% कम पर खरीदता है और MRP से 4% कम पर बेचता है। उसका लाभ प्रतिशत लगभग कितना है?","optionsHi":["8.5%","12.5%","9.7%","8.9%"],"explanationHi":"लाभ = 0.96/0.875 − 1 = 0.0971, लगभग 9.7%। 12.5 − 4 = 8.5% MRP के अंश के रूप में लाभ है, क्रय मूल्य के रूप में नहीं।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-105","question":"Selling an article for ₹960 gives a loss of x%, while selling it for ₹1,410 gives a profit of x%. What is the cost price?","options":["₹1,200","₹1,185","₹1,150","₹1,175"],"answer":1,"explanation":"Equal percentages on the same cost mean equal amounts, so the cost is midway: (960 + 1,410)/2 = ₹1,185.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"किसी वस्तु को ₹960 में बेचने पर x% की हानि होती है, जबकि ₹1,410 में बेचने पर x% का लाभ होता है। क्रय मूल्य क्या है?","optionsHi":["₹1,200","₹1,185","₹1,150","₹1,175"],"explanationHi":"एक ही क्रय मूल्य पर बराबर प्रतिशत का अर्थ बराबर राशि है, अतः क्रय मूल्य ठीक बीच में है: (960 + 1,410)/2 = ₹1,185।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-106","question":"A shopkeeper buys 80 kg of sugar at ₹42 per kg. He sells 30 kg at a 15% profit and 30 kg at a 10% loss. At what price per kg must he sell the remaining 20 kg to make a 10% profit overall?","options":["₹52.50","₹55.65","₹50.40","₹57.75"],"answer":1,"explanation":"Target = 1.1 × 3,360 = ₹3,696. Sales so far = 30 × 48.30 + 30 × 37.80 = ₹2,583. The last 20 kg must bring ₹1,113, i.e. ₹55.65 per kg.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक दुकानदार ₹42 प्रति kg की दर से 80 kg चीनी खरीदता है। वह 30 kg को 15% लाभ पर और 30 kg को 10% हानि पर बेचता है। कुल मिलाकर 10% लाभ कमाने के लिए उसे शेष 20 kg प्रति kg किस मूल्य पर बेचनी होगी?","optionsHi":["₹52.50","₹55.65","₹50.40","₹57.75"],"explanationHi":"लक्ष्य = 1.1 × 3,360 = ₹3,696। अब तक की बिक्री = 30 × 48.30 + 30 × 37.80 = ₹2,583। अंतिम 20 kg से ₹1,113 आने चाहिए, अर्थात् ₹55.65 प्रति kg।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-107","question":"An article is sold for ₹3,600 and the profit is one-fifth of the selling price. What is the profit percent on cost?","options":["25%","20%","16.67%","30%"],"answer":0,"explanation":"Profit = 3,600/5 = ₹720 and cost = ₹2,880. Profit on cost = 720/2,880 = 25%. A 1/5 share of SP is 1/4 of cost.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक वस्तु ₹3,600 में बेची जाती है और लाभ विक्रय मूल्य का पाँचवाँ भाग है। क्रय मूल्य पर लाभ प्रतिशत क्या है?","optionsHi":["25%","20%","16.67%","30%"],"explanationHi":"लाभ = 3,600/5 = ₹720 और क्रय मूल्य = ₹2,880। क्रय मूल्य पर लाभ = 720/2,880 = 25%। विक्रय मूल्य का 1/5 अंश, क्रय मूल्य का 1/4 होता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-108","question":"A shopkeeper buys eggs at ₹60 a dozen. One egg in every dozen breaks, and he sells the rest at ₹6 each. What is his profit percent?","options":["20%","8.33%","12.5%","10%"],"answer":3,"explanation":"Per dozen: cost ₹60, sale = 11 × 6 = ₹66. Profit = 6/60 = 10%.","difficulty":"moderate","source":"SSC CHSL · RRB Group D","questionHi":"एक दुकानदार ₹60 प्रति दर्जन की दर से अंडे खरीदता है। हर दर्जन में एक अंडा टूट जाता है, और वह शेष को ₹6 प्रति अंडा बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","8.33%","12.5%","10%"],"explanationHi":"प्रति दर्जन: लागत ₹60, बिक्री = 11 × 6 = ₹66। लाभ = 6/60 = 10%।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-109","question":"A trader's price of a fan is ₹1,770 including 18% GST, which he passes on to the government. If the fan cost him ₹1,200 before GST, what is his profit percent?","options":["47.5%","20%","25%","22.5%"],"answer":2,"explanation":"His price before GST = 1,770 ÷ 1.18 = ₹1,500. Profit = 300/1,200 = 25%. Comparing 1,770 with 1,200 (47.5%) wrongly counts the tax as profit.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी का एक पंखे का मूल्य 18% GST सहित ₹1,770 है, जिसे वह सरकार को दे देता है। यदि पंखा उसे GST से पहले ₹1,200 में पड़ा, तो उसका लाभ प्रतिशत क्या है?","optionsHi":["47.5%","20%","25%","22.5%"],"explanationHi":"GST से पहले उसका मूल्य = 1,770 ÷ 1.18 = ₹1,500। लाभ = 300/1,200 = 25%। 1,770 की तुलना 1,200 से करने (47.5%) पर कर को भी लाभ गिन लिया जाता है, जो गलत है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-110","question":"A man sells a scooter costing ₹50,000 at a 20% loss. With the money he buys a motorbike and sells it at a 20% profit. What is his overall result?","options":["No profit, no loss","₹2,000 gain","₹2,000 loss","₹4,000 loss"],"answer":2,"explanation":"He gets ₹40,000, which grows by 20% to ₹48,000. Compared with ₹50,000 he is ₹2,000 down: the 20% profit is on a smaller base.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक व्यक्ति ₹50,000 की लागत वाला स्कूटर 20% हानि पर बेचता है। उस धन से वह एक मोटरसाइकिल खरीदता है और उसे 20% लाभ पर बेचता है। उसका कुल परिणाम क्या है?","optionsHi":["न लाभ, न हानि","₹2,000 का लाभ","₹2,000 की हानि","₹4,000 की हानि"],"explanationHi":"उसे ₹40,000 मिलते हैं, जो 20% बढ़कर ₹48,000 हो जाते हैं। ₹50,000 की तुलना में वह ₹2,000 कम है: 20% का लाभ छोटे आधार पर है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-111","question":"A shopkeeper marks his goods 40% above cost and allows a discount of d%, still making a 19% profit. What would happen if he allowed a discount of 2d%?","options":["4% profit","2% loss","No profit, no loss","2% profit"],"answer":1,"explanation":"1.4(1 − d) = 1.19 gives d = 15%. With 30% off, SP = 1.4 × 0.7 = 0.98 of cost, a 2% loss.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक दुकानदार अपना माल क्रय मूल्य से 40% अधिक अंकित करता है और d% की छूट देता है, फिर भी 19% का लाभ कमाता है। यदि वह 2d% की छूट देता, तो क्या होता?","optionsHi":["4% लाभ","2% हानि","न लाभ, न हानि","2% लाभ"],"explanationHi":"1.4(1 − d) = 1.19 से d = 15%। 30% की छूट पर विक्रय मूल्य = 1.4 × 0.7 = क्रय मूल्य का 0.98, यानी 2% की हानि।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-112","question":"A sari costs a merchant ₹2,000. He wants a 20% profit after allowing a 20% discount and paying his agent a 4% commission on the selling price. What should the marked price be?","options":["₹3,125","₹3,000","₹3,250","₹3,200"],"answer":0,"explanation":"He must keep ₹2,400 after commission, so SP = 2,400 ÷ 0.96 = ₹2,500. MP = 2,500 ÷ 0.8 = ₹3,125.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक साड़ी एक व्यापारी को ₹2,000 में पड़ती है। वह 20% की छूट देने और अपने एजेंट को विक्रय मूल्य पर 4% कमीशन देने के बाद 20% का लाभ चाहता है। अंकित मूल्य क्या होना चाहिए?","optionsHi":["₹3,125","₹3,000","₹3,250","₹3,200"],"explanationHi":"कमीशन के बाद उसके पास ₹2,400 बचने चाहिए, अतः विक्रय मूल्य = 2,400 ÷ 0.96 = ₹2,500। अंकित मूल्य = 2,500 ÷ 0.8 = ₹3,125।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-113","question":"A dealer mixes tea costing ₹200 per kg with tea costing ₹300 per kg and sells the blend at ₹330 per kg, making a 20% profit. In what ratio did he mix the two teas?","options":["3 : 1","2 : 3","1 : 2","1 : 3"],"answer":3,"explanation":"Cost of the blend = 330 ÷ 1.2 = ₹275. Alligation: (300 − 275) : (275 − 200) = 25 : 75 = 1 : 3 (cheaper : dearer).","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी ₹200 प्रति kg वाली चाय को ₹300 प्रति kg वाली चाय के साथ मिलाता है और मिश्रण को ₹330 प्रति kg पर बेचकर 20% का लाभ कमाता है। उसने दोनों चायों को किस अनुपात में मिलाया?","optionsHi":["3 : 1","2 : 3","1 : 2","1 : 3"],"explanationHi":"मिश्रण की लागत = 330 ÷ 1.2 = ₹275। एलीगेशन: (300 − 275) : (275 − 200) = 25 : 75 = 1 : 3 (सस्ती : महँगी)।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-114","question":"If a shopkeeper gives a 25% discount on the marked price he loses ₹30, but if he gives a 10% discount he gains ₹60. What is the cost price?","options":["₹450","₹500","₹420","₹480"],"answer":3,"explanation":"The two selling prices differ by 15% of MP = 30 + 60 = ₹90, so MP = ₹600. Cost = 0.75 × 600 + 30 = ₹480.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि एक दुकानदार अंकित मूल्य पर 25% की छूट देता है तो उसे ₹30 की हानि होती है, लेकिन यदि वह 10% की छूट देता है तो उसे ₹60 का लाभ होता है। क्रय मूल्य क्या है?","optionsHi":["₹450","₹500","₹420","₹480"],"explanationHi":"दोनों विक्रय मूल्यों का अंतर अंकित मूल्य का 15% = 30 + 60 = ₹90 है, अतः अंकित मूल्य = ₹600। क्रय मूल्य = 0.75 × 600 + 30 = ₹480।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-115","question":"A wholesaler sells on credit at a 15% profit, but 5% of the sales amount is never recovered. What is his actual profit percent?","options":["10%","9.5%","9.25%","8.75%"],"answer":2,"explanation":"Money received = 1.15 × 0.95 = 1.0925 of cost, a 9.25% profit. 15 − 5 = 10% ignores that the bad debt is 5% of the larger sales figure.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"एक थोक विक्रेता उधार पर 15% लाभ पर बेचता है, लेकिन बिक्री राशि का 5% कभी वसूल नहीं होता। उसका वास्तविक लाभ प्रतिशत क्या है?","optionsHi":["10%","9.5%","9.25%","8.75%"],"explanationHi":"प्राप्त धन = क्रय मूल्य का 1.15 × 0.95 = 1.0925, यानी 9.25% का लाभ। 15 − 5 = 10% इस बात को अनदेखा करता है कि डूबा हुआ कर्ज़ बड़ी बिक्री राशि का 5% है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-116","question":"A dairy buys milk at ₹48 a litre, adds water equal to 20% of the milk's volume and sells the mixture at ₹54 a litre. What is its profit percent?","options":["12.5%","35%","32.5%","30%"],"answer":1,"explanation":"1 L of milk (₹48) becomes 1.2 L, sold for 1.2 × 54 = ₹64.80. Profit = 16.80/48 = 35%. Multipliers: 1.2 × 54/48 = 1.35.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक डेयरी ₹48 प्रति लीटर की दर से दूध खरीदती है, दूध के आयतन के 20% के बराबर पानी मिलाती है और मिश्रण को ₹54 प्रति लीटर बेचती है। उसका लाभ प्रतिशत क्या है?","optionsHi":["12.5%","35%","32.5%","30%"],"explanationHi":"1 L दूध (₹48) बढ़कर 1.2 L हो जाता है, जो 1.2 × 54 = ₹64.80 में बिकता है। लाभ = 16.80/48 = 35%। गुणक: 1.2 × 54/48 = 1.35।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-117","question":"A manufacturer makes a cooler for ₹800 and marks it 50% above cost. He gives a 20% trade discount to a retailer, who sells it at the manufacturer's marked price plus 10% GST. What is the retailer's profit percent?","options":["25%","37.5%","50%","20%"],"answer":0,"explanation":"MP = ₹1,200, so the retailer pays ₹960. He keeps ₹1,200 (the GST goes to the government). Profit = 240/960 = 25%.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक निर्माता एक कूलर ₹800 में बनाता है और उसे लागत से 50% अधिक अंकित करता है। वह एक खुदरा विक्रेता को 20% की व्यापार छूट देता है, जो उसे निर्माता के अंकित मूल्य पर 10% GST जोड़कर बेचता है। खुदरा विक्रेता का लाभ प्रतिशत क्या है?","optionsHi":["25%","37.5%","50%","20%"],"explanationHi":"अंकित मूल्य = ₹1,200, अतः खुदरा विक्रेता ₹960 देता है। वह ₹1,200 रखता है (GST सरकार को जाता है)। लाभ = 240/960 = 25%।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-118","question":"An article costing ₹1,200 is sold at a profit of ₹150. What is the profit percent?","options":["12.5%","15%","11.11%","10%"],"answer":0,"explanation":"Profit % = 150/1,200 × 100 = 12.5%. 11.11% divides by the selling price ₹1,350 instead of the cost.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹1,200 की लागत वाली एक वस्तु ₹150 के लाभ पर बेची जाती है। लाभ प्रतिशत क्या है?","optionsHi":["12.5%","15%","11.11%","10%"],"explanationHi":"लाभ % = 150/1,200 × 100 = 12.5%। 11.11% में क्रय मूल्य के बजाय विक्रय मूल्य ₹1,350 से भाग दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-119","question":"A pair of earphones bought for ₹750 is sold for ₹840. What is the profit percent?","options":["10.71%","9%","15%","12%"],"answer":3,"explanation":"Profit = ₹90 on a cost of ₹750, so profit % = 90/750 × 100 = 12%. 10.71% divides by the selling price ₹840, and 9% treats ₹90 as 9% outright.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"₹750 में खरीदे गए एक ईयरफोन का जोड़ा ₹840 में बेचा जाता है। लाभ प्रतिशत क्या है?","optionsHi":["10.71%","9%","15%","12%"],"explanationHi":"₹750 के क्रय मूल्य पर लाभ ₹90 है, अतः लाभ % = 90/750 × 100 = 12%। 10.71% में विक्रय मूल्य ₹840 से भाग दिया गया है, और 9% में ₹90 को सीधे 9% मान लिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-120","question":"A trader sells a lamp for ₹1,092 at a profit of 5%. What did it cost him?","options":["₹1,037.40","₹1,050","₹1,040","₹1,146.60"],"answer":2,"explanation":"Cost = 1,092 ÷ 1.05 = ₹1,040. Taking 5% off the selling price (₹1,037.40) uses the wrong base.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"एक व्यापारी एक लैंप ₹1,092 में 5% के लाभ पर बेचता है। उसे यह कितने में पड़ा?","optionsHi":["₹1,037.40","₹1,050","₹1,040","₹1,146.60"],"explanationHi":"क्रय मूल्य = 1,092 ÷ 1.05 = ₹1,040। विक्रय मूल्य में से 5% घटाना (₹1,037.40) गलत आधार लेना है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-121","question":"The marked price of a mixer is ₹840, which is 40% above its cost. If it is sold at a 15% discount, what is the profit percent?","options":["25%","19%","21%","15%"],"answer":1,"explanation":"Cost = 840 ÷ 1.4 = ₹600; SP = 0.85 × 840 = ₹714. Profit = 114/600 = 19% (check: 1.4 × 0.85 = 1.19).","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"एक मिक्सर का अंकित मूल्य ₹840 है, जो उसके क्रय मूल्य से 40% अधिक है। यदि इसे 15% की छूट पर बेचा जाए, तो लाभ प्रतिशत क्या है?","optionsHi":["25%","19%","21%","15%"],"explanationHi":"क्रय मूल्य = 840 ÷ 1.4 = ₹600; विक्रय मूल्य = 0.85 × 840 = ₹714। लाभ = 114/600 = 19% (जाँच: 1.4 × 0.85 = 1.19)।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-122","question":"A store gives one shirt free with every four shirts bought. What is the effective discount?","options":["20%","25%","16.67%","80%"],"answer":0,"explanation":"The customer gets 5 shirts for the price of 4, so he saves 1 out of 5 = 20%. 25% wrongly divides by the 4 paid for.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"एक दुकान हर चार कमीज़ें खरीदने पर एक कमीज़ मुफ़्त देती है। प्रभावी छूट क्या है?","optionsHi":["20%","25%","16.67%","80%"],"explanationHi":"ग्राहक को 4 के मूल्य में 5 कमीज़ें मिलती हैं, अतः वह 5 में से 1 की बचत करता है = 20%। 25% में चुकाई गई 4 से गलती से भाग दिया गया है।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-123","question":"The cost price and selling price of an article are in the ratio 4 : 5. If the cost rises by 25% and the selling price by 10%, what is the new profit percent?","options":["10%","15%","12.5%","5%"],"answer":0,"explanation":"New CP = 4 × 1.25 = 5 and new SP = 5 × 1.1 = 5.5. Profit = 0.5/5 = 10%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी वस्तु का क्रय मूल्य और विक्रय मूल्य 4 : 5 के अनुपात में हैं। यदि क्रय मूल्य 25% और विक्रय मूल्य 10% बढ़ जाए, तो नया लाभ प्रतिशत क्या है?","optionsHi":["10%","15%","12.5%","5%"],"explanationHi":"नया क्रय मूल्य = 4 × 1.25 = 5 और नया विक्रय मूल्य = 5 × 1.1 = 5.5। लाभ = 0.5/5 = 10%।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-124","question":"A shopkeeper makes a 5% profit even after allowing a 30% discount. By what percent above cost is the article marked?","options":["35%","45%","40%","50%"],"answer":3,"explanation":"MP × 0.7 = 1.05 × CP, so MP = 1.5 × CP, i.e. 50% above cost. 30 + 5 = 35% is the trap.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"एक दुकानदार 30% की छूट देने के बाद भी 5% का लाभ कमाता है। वस्तु क्रय मूल्य से कितने प्रतिशत अधिक अंकित है?","optionsHi":["35%","45%","40%","50%"],"explanationHi":"अंकित मूल्य × 0.7 = 1.05 × क्रय मूल्य, अतः अंकित मूल्य = 1.5 × क्रय मूल्य, अर्थात् क्रय मूल्य से 50% अधिक। 30 + 5 = 35% जाल है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-125","question":"A trader marks his goods 35% above cost. What discount must he give so that he makes a profit of 8%?","options":["27%","25%","20%","18%"],"answer":2,"explanation":"1.35 × (1 − d) = 1.08 gives 1 − d = 0.8, so d = 20%. 35 − 8 = 27% subtracts on the wrong base.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी अपना माल क्रय मूल्य से 35% अधिक अंकित करता है। 8% का लाभ पाने के लिए उसे कितनी छूट देनी चाहिए?","optionsHi":["27%","25%","20%","18%"],"explanationHi":"1.35 × (1 − d) = 1.08 से 1 − d = 0.8, अतः d = 20%। 35 − 8 = 27% गलत आधार पर घटाना है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-126","question":"A refrigerator is sold at a 12% loss. Had it been sold for ₹3,000 more, there would have been an 8% profit. At what price should it be sold to make a 20% profit?","options":["₹15,000","₹18,000","₹16,200","₹19,500"],"answer":1,"explanation":"The swing from −12% to +8% is 20% of cost = ₹3,000, so cost = ₹15,000. For 20% profit, SP = ₹18,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक रेफ्रिजरेटर 12% की हानि पर बेचा जाता है। यदि वह ₹3,000 अधिक में बिकता, तो 8% का लाभ होता। 20% का लाभ पाने के लिए इसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹15,000","₹18,000","₹16,200","₹19,500"],"explanationHi":"−12% से +8% का अंतर क्रय मूल्य का 20% = ₹3,000 है, अतः क्रय मूल्य = ₹15,000। 20% लाभ के लिए विक्रय मूल्य = ₹18,000।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-127","question":"A retailer buys a smartphone at 20% below its MRP and sells it at 8% below MRP, making a profit of ₹1,800. What is the MRP?","options":["₹22,500","₹15,000","₹9,000","₹12,000"],"answer":1,"explanation":"Profit = (92 − 80)% of MRP = 12% of MRP = ₹1,800, so MRP = ₹15,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"एक खुदरा विक्रेता एक स्मार्टफोन MRP से 20% कम पर खरीदता है और MRP से 8% कम पर बेचकर ₹1,800 का लाभ कमाता है। MRP क्या है?","optionsHi":["₹22,500","₹15,000","₹9,000","₹12,000"],"explanationHi":"लाभ = MRP का (92 − 80)% = MRP का 12% = ₹1,800, अतः MRP = ₹15,000।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-128","question":"A sells an article to B at a 20% profit and B sells it to C at a further 20% profit. C pays ₹440 more than A's cost price. What was A's cost price?","options":["₹1,000","₹1,100","₹2,200","₹880"],"answer":0,"explanation":"C pays 1.2 × 1.2 = 1.44 of A's cost, i.e. 44% more. 44% = ₹440, so A's cost = ₹1,000. Using 40% gives ₹1,100.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A एक वस्तु B को 20% लाभ पर बेचता है और B उसे C को 20% और लाभ पर बेचता है। C, A के क्रय मूल्य से ₹440 अधिक देता है। A का क्रय मूल्य क्या था?","optionsHi":["₹1,000","₹1,100","₹2,200","₹880"],"explanationHi":"C, A के क्रय मूल्य का 1.2 × 1.2 = 1.44 देता है, यानी 44% अधिक। 44% = ₹440, अतः A का क्रय मूल्य = ₹1,000। 40% लेने पर ₹1,100 आता है।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-129","question":"A shoe has an MRP of ₹2,100 including 5% GST. The retailer gives a 10% discount on the MRP (GST remains 5% of the discounted price, included). His cost before GST is ₹1,500. What is his profit percent?","options":["26%","12.5%","40%","20%"],"answer":3,"explanation":"Customer pays 0.9 × 2,100 = ₹1,890, of which the retailer keeps 1,890 ÷ 1.05 = ₹1,800. Profit = 300/1,500 = 20%.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक जूते का MRP 5% GST सहित ₹2,100 है। खुदरा विक्रेता MRP पर 10% की छूट देता है (GST छूट के बाद के मूल्य का 5% ही रहता है, और मूल्य में शामिल है)। GST से पहले उसकी लागत ₹1,500 है। उसका लाभ प्रतिशत क्या है?","optionsHi":["26%","12.5%","40%","20%"],"explanationHi":"ग्राहक 0.9 × 2,100 = ₹1,890 देता है, जिसमें से खुदरा विक्रेता 1,890 ÷ 1.05 = ₹1,800 रखता है। लाभ = 300/1,500 = 20%।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-130","question":"A trader loses 5% when he sells an article at a certain price. If he raises that price by 12%, what is his result?","options":["7% profit","6% profit","6.4% profit","5.4% profit"],"answer":2,"explanation":"New SP = 0.95 × 1.12 = 1.064 of cost, a profit of 6.4%. 12 − 5 = 7% ignores that the 12% is on the lower selling price.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"एक व्यापारी जब किसी वस्तु को एक निश्चित मूल्य पर बेचता है तो उसे 5% की हानि होती है। यदि वह उस मूल्य को 12% बढ़ा दे, तो उसका परिणाम क्या होगा?","optionsHi":["7% लाभ","6% लाभ","6.4% लाभ","5.4% लाभ"],"explanationHi":"नया विक्रय मूल्य = क्रय मूल्य का 0.95 × 1.12 = 1.064, यानी 6.4% का लाभ। 12 − 5 = 7% इस बात को अनदेखा करता है कि 12% कम विक्रय मूल्य पर लगता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-131","question":"A furniture dealer sells a sofa at a 15% profit. Had he sold it for ₹1,890 more, his profit would have been 22%. At what price must he sell it to make a 30% profit?","options":["₹27,000","₹31,050","₹35,100","₹34,500"],"answer":2,"explanation":"The extra 7% of cost = ₹1,890, so cost = ₹27,000. For 30% profit, SP = 1.3 × 27,000 = ₹35,100.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक फर्नीचर डीलर एक सोफा 15% लाभ पर बेचता है। यदि वह इसे ₹1,890 अधिक में बेचता, तो उसका लाभ 22% होता। 30% लाभ पाने के लिए उसे इसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹27,000","₹31,050","₹35,100","₹34,500"],"explanationHi":"क्रय मूल्य का अतिरिक्त 7% = ₹1,890, अतः क्रय मूल्य = ₹27,000। 30% लाभ के लिए विक्रय मूल्य = 1.3 × 27,000 = ₹35,100।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-132","question":"A shopkeeper wanted to mark his goods 60% above cost so as to gain 20% after a 25% discount. By mistake he marked them only 25% above cost but still gave the 25% discount. What was his result?","options":["No profit, no loss","6.25% loss","5% loss","6.25% profit"],"answer":1,"explanation":"SP = 1.25 × 0.75 = 0.9375 of cost, a loss of 6.25%. A markup and a discount of the same percent always end in a loss.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक दुकानदार अपना माल क्रय मूल्य से 60% अधिक अंकित करना चाहता था ताकि 25% की छूट के बाद उसे 20% का लाभ हो। भूल से उसने उसे क्रय मूल्य से केवल 25% अधिक अंकित किया, लेकिन फिर भी 25% की छूट दी। उसका परिणाम क्या रहा?","optionsHi":["न लाभ, न हानि","6.25% हानि","5% हानि","6.25% लाभ"],"explanationHi":"विक्रय मूल्य = 1.25 × 0.75 = क्रय मूल्य का 0.9375, यानी 6.25% की हानि। समान प्रतिशत की अंकन वृद्धि और छूट का अंत हमेशा हानि में होता है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-133","question":"Article A costs 25% more than article B. A is sold at a 20% loss and B at a 35% profit, and together they fetch ₹23,500. What is the overall profit?","options":["₹1,000","₹1,250","₹750","₹1,500"],"answer":0,"explanation":"With B = b: SP = 1.25b × 0.8 + 1.35b = 2.35b = 23,500, so b = ₹10,000. Total cost = 2.25b = ₹22,500, profit = ₹1,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"वस्तु A की लागत वस्तु B से 25% अधिक है। A को 20% हानि पर और B को 35% लाभ पर बेचा जाता है, और दोनों मिलकर ₹23,500 देती हैं। कुल लाभ कितना है?","optionsHi":["₹1,000","₹1,250","₹750","₹1,500"],"explanationHi":"B = b लें: विक्रय मूल्य = 1.25b × 0.8 + 1.35b = 2.35b = 23,500, अतः b = ₹10,000। कुल लागत = 2.25b = ₹22,500, लाभ = ₹1,000।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-134","question":"A merchant sells one-third of his grain at a 10% profit, half of the remainder at a 20% profit and the rest at a 25% loss. What is his overall result?","options":["5% profit","1.67% loss","No profit, no loss","1.67% profit"],"answer":3,"explanation":"Each part is one-third of the stock, so the overall result = (10 + 20 − 25)/3 = 5/3 ≈ 1.67% profit.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी अपने अनाज का एक-तिहाई 10% लाभ पर, शेष का आधा 20% लाभ पर और बाकी 25% हानि पर बेचता है। उसका कुल परिणाम क्या है?","optionsHi":["5% लाभ","1.67% हानि","न लाभ, न हानि","1.67% लाभ"],"explanationHi":"प्रत्येक भाग स्टॉक का एक-तिहाई है, अतः कुल परिणाम = (10 + 20 − 25)/3 = 5/3 ≈ 1.67% लाभ।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-135","question":"Article X costs ₹2,000 more than article Y. X is sold at a 15% profit and Y at a 10% loss, and X fetches ₹3,600 more than Y. What is the cost of Y?","options":["₹7,200","₹5,000","₹4,800","₹5,200"],"answer":3,"explanation":"1.15(y + 2,000) − 0.9y = 3,600 gives 0.25y + 2,300 = 3,600, so y = ₹5,200.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"वस्तु X की लागत वस्तु Y से ₹2,000 अधिक है। X को 15% लाभ पर और Y को 10% हानि पर बेचा जाता है, और X, Y से ₹3,600 अधिक दिलाती है। Y की लागत क्या है?","optionsHi":["₹7,200","₹5,000","₹4,800","₹5,200"],"explanationHi":"1.15(y + 2,000) − 0.9y = 3,600 से 0.25y + 2,300 = 3,600, अतः y = ₹5,200।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-136","question":"Two successive discounts of x% and (x − 10)% are equivalent to a single discount of 44%. What is x?","options":["27","34","30","25"],"answer":2,"explanation":"(1 − x/100)(1.1 − x/100) = 0.56. Trying x = 30: 0.7 × 0.8 = 0.56. So x = 30.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"x% और (x − 10)% की दो क्रमिक छूटें 44% की एकल छूट के समतुल्य हैं। x क्या है?","optionsHi":["27","34","30","25"],"explanationHi":"(1 − x/100)(1.1 − x/100) = 0.56। x = 30 आज़माएँ: 0.7 × 0.8 = 0.56। अतः x = 30।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-137","question":"A builder buys a plot for ₹48 lakh and pays 5% stamp duty on it, then spends ₹29.6 lakh on construction. He sells the house for ₹90 lakh and pays a 2% brokerage on the sale. What is his profit percent?","options":["12.5%","10.25%","8.2%","12.75%"],"answer":1,"explanation":"Cost = 48 + 2.4 + 29.6 = ₹80 lakh. Net receipt = 90 × 0.98 = ₹88.2 lakh. Profit = 8.2/80 = 10.25%.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक बिल्डर ₹48 लाख में एक भूखंड खरीदता है और उस पर 5% स्टाम्प शुल्क देता है, फिर निर्माण पर ₹29.6 लाख खर्च करता है। वह मकान ₹90 लाख में बेचता है और बिक्री पर 2% दलाली देता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["12.5%","10.25%","8.2%","12.75%"],"explanationHi":"लागत = 48 + 2.4 + 29.6 = ₹80 लाख। शुद्ध प्राप्ति = 90 × 0.98 = ₹88.2 लाख। लाभ = 8.2/80 = 10.25%।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-138","question":"A shopkeeper gains 6.25% by selling a geyser for ₹1,904, which includes 12% GST. What price including GST should he charge to gain 25%?","options":["₹2,240","₹2,000","₹2,380","₹2,256"],"answer":0,"explanation":"Pre-GST price = 1,904 ÷ 1.12 = ₹1,700, so cost = 1,700 ÷ 1.0625 = ₹1,600. For 25% gain: 2,000 + 12% GST = ₹2,240.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक दुकानदार एक गीजर 12% GST सहित ₹1,904 में बेचकर 6.25% का लाभ कमाता है। 25% का लाभ कमाने के लिए उसे GST सहित कितना मूल्य लेना चाहिए?","optionsHi":["₹2,240","₹2,000","₹2,380","₹2,256"],"explanationHi":"GST से पहले का मूल्य = 1,904 ÷ 1.12 = ₹1,700, अतः क्रय मूल्य = 1,700 ÷ 1.0625 = ₹1,600। 25% लाभ के लिए: 2,000 + 12% GST = ₹2,240।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-139","question":"A company sells a product to a distributor for ₹720. The distributor's margin is 10% of his selling price, and the retailer's margin is 20% of the MRP at which he sells. What is the MRP?","options":["₹1,000","₹950.40","₹1,036.80","₹960"],"answer":0,"explanation":"Margins on selling price: distributor sells at 720 ÷ 0.9 = ₹800, retailer at 800 ÷ 0.8 = ₹1,000. Treating margins as markups on cost gives ₹950.40.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"एक कंपनी एक उत्पाद वितरक को ₹720 में बेचती है। वितरक का मार्जिन उसके विक्रय मूल्य का 10% है, और खुदरा विक्रेता का मार्जिन उस MRP का 20% है जिस पर वह बेचता है। MRP क्या है?","optionsHi":["₹1,000","₹950.40","₹1,036.80","₹960"],"explanationHi":"विक्रय मूल्य पर मार्जिन: वितरक 720 ÷ 0.9 = ₹800 पर बेचता है, खुदरा विक्रेता 800 ÷ 0.8 = ₹1,000 पर। मार्जिन को क्रय मूल्य पर अंकन वृद्धि मानने पर ₹950.40 आता है।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-140","question":"A person buys two items for ₹1,000 in all. He sells the first at a 20% gain and the second at a 12% loss, and gets back exactly ₹1,000. What did the first item cost?","options":["₹625","₹400","₹350","₹375"],"answer":3,"explanation":"Gain on the first must equal loss on the second: 0.2a = 0.12(1,000 − a), so 0.32a = 120 and a = ₹375.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक व्यक्ति कुल ₹1,000 में दो वस्तुएँ खरीदता है। वह पहली को 20% लाभ पर और दूसरी को 12% हानि पर बेचता है, और ठीक ₹1,000 वापस पाता है। पहली वस्तु की कीमत क्या थी?","optionsHi":["₹625","₹400","₹350","₹375"],"explanationHi":"पहली पर लाभ दूसरी पर हानि के बराबर होना चाहिए: 0.2a = 0.12(1,000 − a), अतः 0.32a = 120 और a = ₹375।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-141","question":"A factory makes 500 units a day at ₹120 each. 4% are defective and sold as scrap at ₹30 each; the rest sell at ₹150 each. What is the daily profit?","options":["₹15,000","₹12,000","₹12,600","₹13,200"],"answer":2,"explanation":"Revenue = 480 × 150 + 20 × 30 = ₹72,600. Cost = 500 × 120 = ₹60,000. Profit = ₹12,600.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"एक कारखाना प्रतिदिन ₹120 प्रति इकाई की दर से 500 इकाइयाँ बनाता है। 4% दोषपूर्ण हैं और ₹30 प्रति इकाई पर कबाड़ के रूप में बिकती हैं; शेष ₹150 प्रति इकाई पर बिकती हैं। दैनिक लाभ क्या है?","optionsHi":["₹15,000","₹12,000","₹12,600","₹13,200"],"explanationHi":"राजस्व = 480 × 150 + 20 × 30 = ₹72,600। लागत = 500 × 120 = ₹60,000। लाभ = ₹12,600।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-142","question":"A man sells 20% of his stock at a 25% profit. At what profit percent must he sell the rest to make a 30% profit overall?","options":["35%","31.25%","32.5%","30%"],"answer":1,"explanation":"Weighted average: 0.2 × 25 + 0.8x = 30, so 0.8x = 25 and x = 31.25%. 35% balances the 5-point shortfall as if both parts were equal, ignoring that the rest is 80% of the stock.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यक्ति अपने स्टॉक का 20% भाग 25% लाभ पर बेचता है। कुल मिलाकर 30% लाभ कमाने के लिए उसे शेष को कितने प्रतिशत लाभ पर बेचना चाहिए?","optionsHi":["35%","31.25%","32.5%","30%"],"explanationHi":"भारित औसत: 0.2 × 25 + 0.8x = 30, अतः 0.8x = 25 और x = 31.25%। 35% में 5 अंक की कमी को ऐसे पूरा किया गया है जैसे दोनों भाग बराबर हों, यह अनदेखा करते हुए कि शेष स्टॉक का 80% है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-143","question":"A sells an article to B at a profit of p%, and B sells it to C at a loss of p%. C pays 4% less than A's cost. What is p?","options":["4","20","16","25"],"answer":1,"explanation":"(1 + p/100)(1 − p/100) = 0.96, so p²/10,000 = 0.04 and p = 20.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"A एक वस्तु B को p% लाभ पर बेचता है, और B उसे C को p% हानि पर बेचता है। C, A के क्रय मूल्य से 4% कम देता है। p क्या है?","optionsHi":["4","20","16","25"],"explanationHi":"(1 + p/100)(1 − p/100) = 0.96, अतः p²/10,000 = 0.04 और p = 20।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-144","question":"A dealer uses a 900 g weight in place of 1 kg and also sells his goods at 5% below cost price. What is his actual profit percentage?","options":["5%","4.5%","11.11%","5.56%"],"answer":3,"explanation":"He gets 0.95 of the cost of 1 kg for goods that cost him only 0.9 of it: 0.95/0.9 = 1.0556, a 5.56% profit. 1.1 × 0.95 (4.5%) wrongly treats the false weight as a 10% mark-up.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी 1 kg के स्थान पर 900 g का बाट प्रयोग करता है और साथ ही अपना माल क्रय मूल्य से 5% कम पर बेचता है। उसका वास्तविक लाभ प्रतिशत क्या है?","optionsHi":["5%","4.5%","11.11%","5.56%"],"explanationHi":"उसे उस माल के लिए, जिसकी लागत उसे केवल 0.9 पड़ी, 1 kg की लागत का 0.95 मिलता है: 0.95/0.9 = 1.0556, यानी 5.56% का लाभ। 1.1 × 0.95 (4.5%) में झूठे बाट को गलती से 10% की अंकन वृद्धि मान लिया गया है।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-145","question":"A trader sells two articles for ₹6,000 each. On one he gains 25% and on the other he loses 20%. What is his overall result?","options":["Gain of 2.5%","No profit, no loss","Loss of 5%","Loss of 2.44%"],"answer":3,"explanation":"Cost prices are 6,000/1.25 = 4,800 and 6,000/0.8 = 7,500: total 12,300 against 12,000 received, a loss of 300/12,300 = 2.44%. Averaging +25 and −20 to get a gain ignores the different cost bases.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी दो वस्तुएँ ₹6,000 प्रत्येक में बेचता है। एक पर उसे 25% लाभ और दूसरी पर 20% हानि होती है। उसका कुल परिणाम क्या है?","optionsHi":["2.5% का लाभ","न लाभ, न हानि","5% की हानि","2.44% की हानि"],"explanationHi":"क्रय मूल्य 6,000/1.25 = 4,800 और 6,000/0.8 = 7,500 हैं: कुल 12,300 के सामने 12,000 मिले, अतः हानि = 300/12,300 = 2.44%। +25 और −20 का औसत लेकर लाभ निकालना अलग-अलग क्रय आधारों को अनदेखा करता है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-146","question":"A shop marks goods 50% above cost, then offers 10% off the marked price together with 'buy 4, get 1 free'. What is its profit percentage?","options":["35%","20%","8%","1.25%"],"answer":2,"explanation":"For 5 items it receives 4 × 0.9 × 1.5 C = 5.4C against a cost of 5C, so profit = 8%. Ignoring the free item gives 35%; treating the offer as 25% off gives 1.25%.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक दुकान माल को क्रय मूल्य से 50% अधिक अंकित करती है, फिर अंकित मूल्य पर 10% की छूट के साथ '4 खरीदें, 1 मुफ़्त पाएँ' की पेशकश करती है। उसका लाभ प्रतिशत क्या है?","optionsHi":["35%","20%","8%","1.25%"],"explanationHi":"5 वस्तुओं के लिए उसे 4 × 0.9 × 1.5 C = 5.4C मिलता है, जबकि लागत 5C है, अतः लाभ = 8%। मुफ़्त वस्तु को अनदेखा करने पर 35% आता है; पेशकश को 25% की छूट मानने पर 1.25%।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-147","question":"A shopkeeper sells an article at 12% profit. Had he bought it 10% cheaper and sold it for ₹33 less, he would have made 20% profit. What is the cost price?","options":["₹825","₹412.50","₹275","₹1,100"],"answer":0,"explanation":"Old SP = 1.12x; new SP = 1.2 × 0.9x = 1.08x = 1.12x − 33, so 0.04x = 33 and x = ₹825. Dividing 33 by the gap in profit rates (8%) gives ₹412.50.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दुकानदार एक वस्तु 12% लाभ पर बेचता है। यदि वह उसे 10% सस्ता खरीदता और ₹33 कम में बेचता, तो उसे 20% लाभ होता। क्रय मूल्य क्या है?","optionsHi":["₹825","₹412.50","₹275","₹1,100"],"explanationHi":"पुराना विक्रय मूल्य = 1.12x; नया विक्रय मूल्य = 1.2 × 0.9x = 1.08x = 1.12x − 33, अतः 0.04x = 33 और x = ₹825। 33 को लाभ दरों के अंतर (8%) से भाग देने पर ₹412.50 आता है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-148","question":"By selling 45 pens, a shopkeeper loses an amount equal to the selling price of 9 pens. What is his loss percentage?","options":["20%","25%","83.33%","16.67%"],"answer":3,"explanation":"45C − 45S = 9S, so 54S = 45C and S = (5/6)C: a loss of 16.67%. 20% takes the loss as 9/45 of the cost, but the 9 pens are valued at selling price.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"45 पेन बेचने पर एक दुकानदार को 9 पेनों के विक्रय मूल्य के बराबर हानि होती है। उसका हानि प्रतिशत क्या है?","optionsHi":["20%","25%","83.33%","16.67%"],"explanationHi":"45C − 45S = 9S, अतः 54S = 45C और S = (5/6)C: 16.67% की हानि। 20% में हानि को लागत का 9/45 लिया गया है, जबकि 9 पेनों का मूल्य विक्रय मूल्य पर आँका जाता है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-149","question":"A dealer offers successive discounts of 20%, 10% and 5% on the marked price. What single discount is equivalent to these?","options":["35%","31.6%","28%","68.4%"],"answer":1,"explanation":"The buyer pays 0.8 × 0.9 × 0.95 = 0.684 of the price, so the single discount is 31.6%. Adding the discounts gives 35%; 68.4% is what is paid, not the discount.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी अंकित मूल्य पर 20%, 10% और 5% की क्रमिक छूटें देता है। इनके समतुल्य एकल छूट क्या है?","optionsHi":["35%","31.6%","28%","68.4%"],"explanationHi":"खरीदार मूल्य का 0.8 × 0.9 × 0.95 = 0.684 देता है, अतः एकल छूट 31.6% है। छूटों को जोड़ने पर 35% आता है; 68.4% वह है जो चुकाया जाता है, छूट नहीं।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-150","question":"A trader marks his goods so that after a 20% discount he still makes a 20% profit. A customer then bargains a further 12.5% off the discounted price. What is the trader's result on this sale?","options":["5% profit","7.5% profit","1.25% profit","2% loss"],"answer":0,"explanation":"MP = 1.2/0.8 = 1.5C; the final price is 1.5 × 0.8 × 0.875 = 1.05C, a 5% profit. Taking the mark-up as 20% + 20% = 40% gives 0.98C, a 2% loss; subtracting 12.5 from 20 gives 7.5%.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक व्यापारी अपना माल इस प्रकार अंकित करता है कि 20% की छूट के बाद भी उसे 20% का लाभ हो। फिर एक ग्राहक छूट के बाद के मूल्य पर 12.5% और कम कराने के लिए मोलभाव करता है। इस बिक्री पर व्यापारी को कितना लाभ या हानि होगी?","optionsHi":["5% लाभ","7.5% लाभ","1.25% लाभ","2% हानि"],"explanationHi":"अंकित मूल्य = 1.2/0.8 = 1.5C; अंतिम मूल्य = 1.5 × 0.8 × 0.875 = 1.05C, यानी 5% लाभ। अंकन वृद्धि को 20% + 20% = 40% लेने पर 0.98C, यानी 2% की हानि आती है; 20 में से 12.5 घटाने पर 7.5% आता है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-151","question":"A man buys a used car for ₹2,40,000, spends ₹30,000 on repairs and ₹6,000 on registration, and sells it for ₹3,03,600. What is his profit percentage?","options":["26.5%","12.44%","10%","9.09%"],"answer":2,"explanation":"Total cost = ₹2,76,000, profit = ₹27,600, i.e. 10%. Measuring against ₹2,40,000 alone gives 26.5%; dividing by the selling price gives 9.09%.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति एक पुरानी कार ₹2,40,000 में खरीदता है, मरम्मत पर ₹30,000 और पंजीकरण पर ₹6,000 खर्च करता है, और उसे ₹3,03,600 में बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["26.5%","12.44%","10%","9.09%"],"explanationHi":"कुल लागत = ₹2,76,000, लाभ = ₹27,600, यानी 10%। केवल ₹2,40,000 के आधार पर मापने पर 26.5% आता है; विक्रय मूल्य से भाग देने पर 9.09%।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-152","question":"A sells a cycle to B at 25% profit, B sells it to C at 20% loss and C sells it to D at 12.5% profit. D pays ₹5,400. What did A pay for it?","options":["₹4,595.74","₹4,800","₹4,252.50","₹6,075"],"answer":1,"explanation":"The overall factor is 1.25 × 0.8 × 1.125 = 1.125, so A paid 5,400/1.125 = ₹4,800. Adding the rates (+17.5%) gives ₹4,595.74; applying the factors to D's price gives ₹6,075.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A एक साइकिल B को 25% लाभ पर बेचता है, B उसे C को 20% हानि पर बेचता है और C उसे D को 12.5% लाभ पर बेचता है। D ₹5,400 देता है। A ने उसे कितने में खरीदा था?","optionsHi":["₹4,595.74","₹4,800","₹4,252.50","₹6,075"],"explanationHi":"कुल गुणक 1.25 × 0.8 × 1.125 = 1.125 है, अतः A ने 5,400/1.125 = ₹4,800 दिए। दरों को जोड़ने (+17.5%) पर ₹4,595.74 आता है; D के मूल्य पर गुणकों को लगाने पर ₹6,075।","subtopic":"successive-selling"},
  {"id":"quant-profit-loss-153","question":"While buying, a trader uses a false weight and gets 1.1 kg of goods for the price of 1 kg. While selling, he hands over only 800 g for every 1 kg he charges for. He also sells at a price per kg 4% below the price per kg he pays his supplier. What is his overall profit percentage?","options":["32%","26%","26.72%","37.5%"],"answer":0,"explanation":"If the supplier charges ₹1 per kg, ₹1 buys 1.1 kg, and every ₹0.96 he charges hands over only 0.8 kg, so the 1.1 kg brings in 1.1/0.8 × 0.96 = ₹1.32: a 32% profit. Treating '800 g for 1 kg' as a 20% gain (× 1.2) gives 26.72%, and ignoring the 4% cut gives 37.5%.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"खरीदते समय एक व्यापारी झूठे बाट से 1 kg के मूल्य में 1.1 kg माल ले लेता है। बेचते समय वह हर 1 kg के दाम में केवल 800 g माल देता है। साथ ही वह प्रति kg उस मूल्य से 4% कम पर बेचता है जो वह अपने आपूर्तिकर्ता को प्रति kg चुकाता है। उसका कुल लाभ प्रतिशत क्या है?","optionsHi":["32%","26%","26.72%","37.5%"],"explanationHi":"यदि आपूर्तिकर्ता ₹1 प्रति kg लेता है, तो ₹1 में 1.1 kg मिलता है, और वह हर ₹0.96 लेकर केवल 0.8 kg देता है, अतः 1.1 kg से 1.1/0.8 × 0.96 = ₹1.32 मिलते हैं: 32% लाभ। '1 kg के बदले 800 g' को 20% लाभ (× 1.2) मानने पर 26.72% आता है, और 4% की कटौती छोड़ देने पर 37.5%।","subtopic":"dishonest-dealer"},
  {"id":"quant-profit-loss-154","question":"Selling an article for ₹1,140 causes a loss, while selling it for ₹1,410 gives a profit equal to twice that loss. What is the cost price?","options":["₹1,275","₹1,320","₹1,230","₹1,050"],"answer":2,"explanation":"(C − 1,140) × 2 = 1,410 − C gives 3C = 3,690, C = ₹1,230. ₹1,275 is the midpoint, which would mean equal profit and loss; ₹1,320 makes the loss twice the profit.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"किसी वस्तु को ₹1,140 में बेचने पर हानि होती है, जबकि ₹1,410 में बेचने पर उस हानि के दोगुने के बराबर लाभ होता है। क्रय मूल्य क्या है?","optionsHi":["₹1,275","₹1,320","₹1,230","₹1,050"],"explanationHi":"(C − 1,140) × 2 = 1,410 − C से 3C = 3,690, C = ₹1,230। ₹1,275 मध्य बिंदु है, जिसका अर्थ होता लाभ और हानि बराबर; ₹1,320 में हानि को लाभ का दोगुना कर दिया गया है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-155","question":"If a shop allows a 25% discount on an article it loses ₹50, but if it allows a 10% discount it gains ₹100. What profit percentage would it make by selling at the marked price?","options":["25%","20%","12.5%","33.33%"],"answer":0,"explanation":"The extra 15% of MP is worth ₹150, so MP = ₹1,000 and CP = 750 + 50 = ₹800; selling at MP gains 200/800 = 25%. 20% measures the gain on the marked price; 33.33% wrongly takes CP = 750.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि एक दुकान किसी वस्तु पर 25% की छूट देती है तो उसे ₹50 की हानि होती है, लेकिन यदि वह 10% की छूट देती है तो उसे ₹100 का लाभ होता है। अंकित मूल्य पर बेचने से उसे कितने प्रतिशत लाभ होगा?","optionsHi":["25%","20%","12.5%","33.33%"],"explanationHi":"अंकित मूल्य का अतिरिक्त 15% ₹150 के बराबर है, अतः अंकित मूल्य = ₹1,000 और क्रय मूल्य = 750 + 50 = ₹800; अंकित मूल्य पर बेचने से लाभ 200/800 = 25%। 20% अंकित मूल्य पर लाभ मापता है; 33.33% में गलती से क्रय मूल्य 750 ले लिया गया है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-156","question":"A vendor buys bananas at 10 for ₹9 and sells them at 9 for ₹10. What is his profit percentage?","options":["23.46%","21%","20%","11.11%"],"answer":0,"explanation":"Cost per banana 0.9, selling price 10/9 = 1.111: profit = 1.111/0.9 − 1 = 23.46%. 21% (1.1 × 1.1) and 20% (10 + 10) both wrongly treat each side as a 10% change.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक विक्रेता केले ₹9 के 10 की दर से खरीदता है और ₹10 के 9 की दर से बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["23.46%","21%","20%","11.11%"],"explanationHi":"प्रति केला क्रय मूल्य 0.9, विक्रय मूल्य 10/9 = 1.111: लाभ = 1.111/0.9 − 1 = 23.46%। 21% (1.1 × 1.1) और 20% (10 + 10) दोनों में प्रत्येक पक्ष को 10% का परिवर्तन मान लिया गया है, जो गलत है।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-157","question":"A trader wants a 20% profit on cost, but by mistake he takes 20% of the selling price as his profit when fixing the price. If the cost price is ₹2,400, how much more than intended does he charge?","options":["₹0","₹480","₹120","₹600"],"answer":2,"explanation":"Intended SP = 2,400 × 1.2 = ₹2,880. Mistaken: SP − 0.2 SP = 2,400 gives SP = ₹3,000. He charges ₹120 more. ₹600 is his mistaken profit, not the difference.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी क्रय मूल्य पर 20% लाभ चाहता है, लेकिन भूल से मूल्य निर्धारित करते समय वह विक्रय मूल्य का 20% अपना लाभ मान लेता है। यदि क्रय मूल्य ₹2,400 है, तो वह इच्छित मूल्य से कितना अधिक लेता है?","optionsHi":["₹0","₹480","₹120","₹600"],"explanationHi":"इच्छित विक्रय मूल्य = 2,400 × 1.2 = ₹2,880। गलत तरीके से: विक्रय मूल्य − 0.2 विक्रय मूल्य = 2,400 से विक्रय मूल्य = ₹3,000। वह ₹120 अधिक लेता है। ₹600 उसका गलत लाभ है, अंतर नहीं।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-158","question":"A dealer allows a 12.5% discount on the marked price and still makes a 22.5% profit. If the cost price is ₹2,000, what is the marked price?","options":["₹2,756.25","₹2,700","₹2,800","₹2,450"],"answer":2,"explanation":"SP = 2,000 × 1.225 = ₹2,450 and MP = 2,450/0.875 = ₹2,800. Adding 12.5% to the SP gives ₹2,756.25; adding the two rates to the cost gives ₹2,700.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी अंकित मूल्य पर 12.5% की छूट देता है और फिर भी 22.5% का लाभ कमाता है। यदि क्रय मूल्य ₹2,000 है, तो अंकित मूल्य क्या है?","optionsHi":["₹2,756.25","₹2,700","₹2,800","₹2,450"],"explanationHi":"विक्रय मूल्य = 2,000 × 1.225 = ₹2,450 और अंकित मूल्य = 2,450/0.875 = ₹2,800। विक्रय मूल्य में 12.5% जोड़ने पर ₹2,756.25 आता है; क्रय मूल्य में दोनों दरें जोड़ने पर ₹2,700।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-159","question":"A man buys two horses for ₹48,000 in all. He sells one at a 15% loss and the other at a 19% gain, and finds that both fetch the same price. What is his overall result?","options":["Gain of 2%","Loss of 0.83%","No profit, no loss","Gain of 4%"],"answer":1,"explanation":"0.85A = 1.19B gives A : B = 7 : 5, so A = ₹28,000 and B = ₹20,000; each sells for ₹23,800. Total ₹47,600 against ₹48,000 is a loss of 400/48,000 = 0.83%. Averaging −15 and +19 ignores the unequal costs.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यक्ति कुल ₹48,000 में दो घोड़े खरीदता है। वह एक को 15% हानि पर और दूसरे को 19% लाभ पर बेचता है, और पाता है कि दोनों से समान मूल्य मिलता है। उसका कुल परिणाम क्या है?","optionsHi":["2% का लाभ","0.83% की हानि","न लाभ, न हानि","4% का लाभ"],"explanationHi":"0.85A = 1.19B से A : B = 7 : 5, अतः A = ₹28,000 और B = ₹20,000; प्रत्येक ₹23,800 में बिकता है। कुल ₹47,600, ₹48,000 के सामने 400/48,000 = 0.83% की हानि है। −15 और +19 का औसत लेना असमान लागतों को अनदेखा करता है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-160","question":"Three offers on the same item: A — 'buy 3, get 2 free'; B — a flat 35% discount; C — two successive discounts of 20% each. Which offer is best for the buyer?","options":["Offer B","Offer C","All three are equal","Offer A"],"answer":3,"explanation":"A: pay for 3, get 5, a 40% discount. B: 35%. C: 1 − 0.8² = 36%. So A is best. Reading C as 40% (20 + 20) makes A and C look equal.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक ही वस्तु पर तीन ऑफ़र: A — '3 खरीदें, 2 मुफ़्त पाएँ'; B — सीधे 35% की छूट; C — 20%-20% की दो क्रमिक छूटें। खरीदार के लिए कौन-सा ऑफ़र सबसे अच्छा है?","optionsHi":["ऑफ़र B","ऑफ़र C","तीनों बराबर हैं","ऑफ़र A"],"explanationHi":"A: 3 का भुगतान, 5 मिलती हैं, यानी 40% की छूट। B: 35%। C: 1 − 0.8² = 36%। अतः A सबसे अच्छा है। C को 40% (20 + 20) पढ़ने पर A और C बराबर दिखते हैं।","subtopic":"successive-discounts"},
  {"id":"quant-profit-loss-161","question":"A shopkeeper marks his goods 30% above cost. He sells half his stock at the marked price, a quarter at 20% off and the rest at 40% off. What is his overall profit percentage?","options":["15%","4%","10.5%","25.5%"],"answer":2,"explanation":"Average realisation = 0.5 + 0.25(0.8) + 0.25(0.6) = 0.85 of MP, and 1.3 × 0.85 = 1.105: 10.5% profit. Averaging the three discounts equally (20%) instead of by quantity gives 4%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दुकानदार अपना माल क्रय मूल्य से 30% अधिक अंकित करता है। वह अपने स्टॉक का आधा अंकित मूल्य पर, एक-चौथाई 20% की छूट पर और शेष 40% की छूट पर बेचता है। उसका कुल लाभ प्रतिशत क्या है?","optionsHi":["15%","4%","10.5%","25.5%"],"explanationHi":"औसत प्राप्ति = अंकित मूल्य का 0.5 + 0.25(0.8) + 0.25(0.6) = 0.85, और 1.3 × 0.85 = 1.105: 10.5% लाभ। तीनों छूटों का मात्रा के बजाय बराबर औसत (20%) लेने पर 4% आता है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-162","question":"If the selling price of an article is increased by 50%, the profit becomes four times as large. What is the original profit percentage?","options":["20%","50%","33.33%","16.67%"],"answer":0,"explanation":"1.5S − C = 4(S − C) gives 3C = 2.5S, so S = 1.2C: profit 20%. 16.67% is the same profit measured on the selling price.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि किसी वस्तु का विक्रय मूल्य 50% बढ़ा दिया जाए, तो लाभ चार गुना हो जाता है। मूल लाभ प्रतिशत क्या है?","optionsHi":["20%","50%","33.33%","16.67%"],"explanationHi":"1.5S − C = 4(S − C) से 3C = 2.5S, अतः S = 1.2C: लाभ 20%। 16.67% विक्रय मूल्य पर मापा गया वही लाभ है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-163","question":"A merchant mixes tea costing ₹320/kg and ₹450/kg in the ratio 3 : 2 and sells the blend at ₹444/kg. What is his profit percentage?","options":["15.32%","19.35%","11.56%","16.22%"],"answer":1,"explanation":"Blend cost = (3×320 + 2×450)/5 = ₹372/kg, so profit = 72/372 = 19.35%. A simple average of 385 gives 15.32%; mixing 2 : 3 by mistake gives 11.56%; 16.22% divides by the selling price.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक व्यापारी ₹320/kg और ₹450/kg वाली चाय को 3 : 2 के अनुपात में मिलाता है और मिश्रण को ₹444/kg पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["15.32%","19.35%","11.56%","16.22%"],"explanationHi":"मिश्रण की लागत = (3×320 + 2×450)/5 = ₹372/kg, अतः लाभ = 72/372 = 19.35%। 385 का साधारण औसत लेने पर 15.32% आता है; भूल से 2 : 3 मिलाने पर 11.56%; 16.22% में विक्रय मूल्य से भाग दिया गया है।","subtopic":"combined-transactions"},
  {"id":"quant-profit-loss-164","question":"A watch sold for ₹1,836 gives the seller an 8% profit. At what price should it be sold to make a 15% profit?","options":["₹1,964.52","₹1,955","₹2,111.40","₹1,700"],"answer":1,"explanation":"CP = 1,836/1.08 = ₹1,700, so the new price is 1,700 × 1.15 = ₹1,955. Adding 7% to the old selling price gives ₹1,964.52, the wrong base.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹1,836 में बेची गई एक घड़ी विक्रेता को 8% का लाभ देती है। 15% का लाभ पाने के लिए इसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹1,964.52","₹1,955","₹2,111.40","₹1,700"],"explanationHi":"क्रय मूल्य = 1,836/1.08 = ₹1,700, अतः नया मूल्य = 1,700 × 1.15 = ₹1,955। पुराने विक्रय मूल्य में 7% जोड़ने पर ₹1,964.52 आता है, जो गलत आधार है।","subtopic":"cp-sp-basics"},
  {"id":"quant-profit-loss-165","question":"A shopkeeper allows a 10% discount on the marked price and still gains 17%. What would his gain have been if he had sold at the marked price?","options":["27%","28.7%","25%","30%"],"answer":3,"explanation":"0.9 MP = 1.17C gives MP = 1.3C, a 30% gain. 27% adds 10 to 17; 28.7% multiplies 1.17 by 1.1.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दुकानदार अंकित मूल्य पर 10% की छूट देता है और फिर भी 17% का लाभ कमाता है। यदि वह अंकित मूल्य पर बेचता, तो उसका लाभ कितना होता?","optionsHi":["27%","28.7%","25%","30%"],"explanationHi":"0.9 अंकित मूल्य = 1.17C से अंकित मूल्य = 1.3C, यानी 30% का लाभ। 27% में 17 के साथ 10 जोड़ दिया गया है; 28.7% में 1.17 को 1.1 से गुणा किया गया है।","subtopic":"marked-price-discount"},
  {"id":"quant-profit-loss-166","question":"A retailer gets 60 pens for the marked price of 50 pens from a wholesaler. He sells them at a 4% discount on the marked price. What is his profit percentage?","options":["20%","15.2%","16%","12.67%"],"answer":1,"explanation":"Each pen costs 50/60 of its marked price, and he gets 0.96 of it: 0.96 × 60/50 = 1.152, so 15.2%. Subtracting 4 from 20 gives 16%; calling the deal a 16.67% discount gives 12.67%.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक खुदरा विक्रेता को थोक विक्रेता से 50 पेनों के अंकित मूल्य पर 60 पेन मिलते हैं। वह उन्हें अंकित मूल्य पर 4% की छूट देकर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","15.2%","16%","12.67%"],"explanationHi":"प्रत्येक पेन की लागत उसके अंकित मूल्य का 50/60 है, और उसे उसका 0.96 मिलता है: 0.96 × 60/50 = 1.152, अतः 15.2%। 20 में से 4 घटाने पर 16% आता है; सौदे को 16.67% की छूट मानने पर 12.67%।","subtopic":"articles-ratio"},
  {"id":"quant-profit-loss-167","question":"An article sold for ₹750 gives a profit of 25%. At what price must it be sold to incur a loss of 12%?","options":["₹540","₹552","₹528","₹510"],"answer":2,"explanation":"Cost price = 750/1.25 = ₹600. For a 12% loss, SP = 600 × 0.88 = ₹528.","difficulty":"moderate","questionHi":"₹750 में बेचने पर एक वस्तु पर 25% लाभ होता है। 12% हानि के लिए उसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹540","₹552","₹528","₹510"],"explanationHi":"क्रय मूल्य = 750/1.25 = ₹600। 12% हानि के लिए विक्रय मूल्य = 600 × 0.88 = ₹528।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-168","question":"A trader sells an article at a profit of 20%. Had he bought it for 10% less and sold it for ₹30 less, his profit would have been 25%. What is the cost price?","options":["₹400","₹450","₹360","₹500"],"answer":0,"explanation":"Let CP = c. Original SP = 1.2c. New CP = 0.9c and new SP = 1.2c − 30 = 1.25 × 0.9c = 1.125c, so 0.075c = 30 and c = ₹400.","difficulty":"very-hard","questionHi":"एक व्यापारी एक वस्तु 20% लाभ पर बेचता है। यदि वह उसे 10% कम में खरीदता और ₹30 कम में बेचता, तो उसका लाभ 25% होता। क्रय मूल्य क्या है?","optionsHi":["₹400","₹450","₹360","₹500"],"explanationHi":"मान लें क्रय मूल्य = c। मूल विक्रय मूल्य = 1.2c। नया क्रय मूल्य = 0.9c और नया विक्रय मूल्य = 1.2c − 30 = 1.25 × 0.9c = 1.125c, अतः 0.075c = 30 और c = ₹400।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-169","question":"A trader's profit is 20% of the selling price. What is his profit percentage on the cost price?","options":["20%","16.67%","30%","25%"],"answer":3,"explanation":"Take SP = 100: profit = 20 and CP = 80, so profit on cost = 20/80 = 25%.","difficulty":"moderate","questionHi":"एक व्यापारी का लाभ विक्रय मूल्य का 20% है। क्रय मूल्य पर उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","16.67%","30%","25%"],"explanationHi":"विक्रय मूल्य = 100 लें: लाभ = 20 और क्रय मूल्य = 80, अतः क्रय मूल्य पर लाभ = 20/80 = 25%।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-170","question":"An article sold for ₹630 gives a loss of 10%. At what price must it be sold to gain 15%?","options":["₹770","₹805","₹840","₹795"],"answer":1,"explanation":"Cost price = 630/0.9 = ₹700. Selling for a 15% gain needs 700 × 1.15 = ₹805.","difficulty":"moderate","questionHi":"₹630 में बेचने पर एक वस्तु पर 10% हानि होती है। 15% लाभ के लिए उसे किस मूल्य पर बेचना चाहिए?","optionsHi":["₹770","₹805","₹840","₹795"],"explanationHi":"क्रय मूल्य = 630/0.9 = ₹700। 15% लाभ के लिए 700 × 1.15 = ₹805 पर बेचना होगा।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-171","question":"A trader sells an article for ₹3,360 and earns a 20% profit. If its cost price had been 10% higher and the selling price the same, what would the profit percentage have been?","options":["10%","9.09%","8%","11.11%"],"answer":1,"explanation":"Original CP = 3,360/1.2 = ₹2,800. The higher CP is ₹3,080, so profit = 280 and the percentage is 280/3,080 = 9.09% (not 10%, because the base changed).","difficulty":"very-hard","questionHi":"एक व्यापारी एक वस्तु ₹3,360 में बेचकर 20% लाभ कमाता है। यदि उसका क्रय मूल्य 10% अधिक होता और विक्रय मूल्य वही रहता, तो लाभ प्रतिशत क्या होता?","optionsHi":["10%","9.09%","8%","11.11%"],"explanationHi":"मूल क्रय मूल्य = 3,360/1.2 = ₹2,800। बढ़ा हुआ क्रय मूल्य ₹3,080 है, अतः लाभ = 280 और प्रतिशत 280/3,080 = 9.09% (10% नहीं, क्योंकि आधार बदल गया)।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-172","question":"The price of an article including 10% GST is ₹1,320. The shopkeeper earns a 20% profit on the pre-tax selling price. What is the cost price?","options":["₹1,100","₹1,056","₹1,200","₹1,000"],"answer":3,"explanation":"Pre-tax price = 1,320/1.1 = ₹1,200. This is 120% of the cost, so CP = 1,200/1.2 = ₹1,000.","difficulty":"hard","questionHi":"10% GST सहित एक वस्तु का मूल्य ₹1,320 है। दुकानदार कर-पूर्व विक्रय मूल्य पर 20% लाभ कमाता है। क्रय मूल्य क्या है?","optionsHi":["₹1,100","₹1,056","₹1,200","₹1,000"],"explanationHi":"कर-पूर्व मूल्य = 1,320/1.1 = ₹1,200। यह क्रय मूल्य का 120% है, अतः क्रय मूल्य = 1,200/1.2 = ₹1,000।","subtopic":"cp-sp-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-173","question":"A shopkeeper marks his goods 40% above cost and then sells 20 articles for the marked price of 16 articles. What is his overall profit percentage?","options":["12%","40%","20%","8%"],"answer":0,"explanation":"Let cost per article = 100. Revenue from 20 articles = 16 × 140 = 2,240 and their cost = 2,000, so profit = 240/2,000 = 12%.","difficulty":"hard","questionHi":"एक दुकानदार अपने माल पर क्रय मूल्य से 40% ऊपर अंकित मूल्य लिखता है और फिर 16 वस्तुओं के अंकित मूल्य पर 20 वस्तुएँ बेचता है। उसका कुल लाभ प्रतिशत क्या है?","optionsHi":["12%","40%","20%","8%"],"explanationHi":"प्रति वस्तु क्रय मूल्य = 100 मानें। 20 वस्तुओं से प्राप्ति = 16 × 140 = 2,240 और उनकी लागत = 2,000, अतः लाभ = 240/2,000 = 12%।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-174","question":"By selling 45 oranges for ₹40, a vendor loses 20%. How many oranges should he sell for ₹24 to gain 20%?","options":["20","24","18","16"],"answer":2,"explanation":"Cost of 45 oranges = 40/0.8 = ₹50, i.e. ₹10/9 each. For a 20% gain each must sell at ₹4/3, so ₹24 buys 24 ÷ (4/3) = 18 oranges.","difficulty":"very-hard","questionHi":"45 संतरे ₹40 में बेचने पर एक विक्रेता को 20% हानि होती है। 20% लाभ के लिए उसे ₹24 में कितने संतरे बेचने चाहिए?","optionsHi":["20","24","18","16"],"explanationHi":"45 संतरों का क्रय मूल्य = 40/0.8 = ₹50, अर्थात् प्रति संतरा ₹10/9। 20% लाभ के लिए प्रत्येक ₹4/3 में बेचना होगा, अतः ₹24 में 24 ÷ (4/3) = 18 संतरे।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-175","question":"A fruit seller buys oranges at 5 for ₹4 and sells them at 4 for ₹5. What is his profit percentage?","options":["25%","50%","62.5%","56.25%"],"answer":3,"explanation":"Cost per orange = 4/5 = ₹0.80 and selling price per orange = 5/4 = ₹1.25. Profit = 0.45/0.80 = 56.25%.","difficulty":"very-hard","questionHi":"एक फल विक्रेता संतरे 5 के ₹4 की दर से खरीदता है और 4 के ₹5 की दर से बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["25%","50%","62.5%","56.25%"],"explanationHi":"प्रति संतरा क्रय मूल्य = 4/5 = ₹0.80 और प्रति संतरा विक्रय मूल्य = 5/4 = ₹1.25। लाभ = 0.45/0.80 = 56.25%।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-176","question":"On selling 20 articles, a trader's gain equals the selling price of 4 articles. What is his profit percentage?","options":["20%","25%","16.67%","40%"],"answer":1,"explanation":"Gain = SP of 4 means SP of 20 − CP of 20 = SP of 4, so CP of 20 = SP of 16. Profit = (20 − 16)/16 = 25% on the cost.","difficulty":"hard","questionHi":"20 वस्तुएँ बेचने पर एक व्यापारी का लाभ 4 वस्तुओं के विक्रय मूल्य के बराबर है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","25%","16.67%","40%"],"explanationHi":"लाभ = 4 वस्तुओं का विक्रय मूल्य, अतः 20 वस्तुओं का वि.मू. − 20 वस्तुओं का क्र.मू. = 4 वस्तुओं का वि.मू., अर्थात् 20 का क्र.मू. = 16 का वि.मू.। लाभ = (20 − 16)/16 = 25%।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-177","question":"On selling 25 articles, a trader's loss equals the selling price of 5 articles. What is his loss percentage?","options":["20%","25%","16.67%","14.29%"],"answer":2,"explanation":"Loss = CP of 25 − SP of 25 = SP of 5, so CP of 25 = SP of 30. Loss% = (30 − 25)/30 = 16.67% of the cost.","difficulty":"very-hard","questionHi":"25 वस्तुएँ बेचने पर एक व्यापारी की हानि 5 वस्तुओं के विक्रय मूल्य के बराबर है। उसका हानि प्रतिशत क्या है?","optionsHi":["20%","25%","16.67%","14.29%"],"explanationHi":"हानि = 25 का क्र.मू. − 25 का वि.मू. = 5 का वि.मू., अतः 25 का क्र.मू. = 30 का वि.मू.। हानि% = (30 − 25)/30 = 16.67%।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-178","question":"A shopkeeper buys 8 pens for ₹100 and sells 5 pens for ₹80. What is his profit percentage?","options":["28%","25%","30%","20%"],"answer":0,"explanation":"Cost per pen = 100/8 = ₹12.50 and selling price per pen = 80/5 = ₹16. Profit = 3.50/12.50 = 28%.","difficulty":"hard","questionHi":"एक दुकानदार 8 पेन ₹100 में खरीदता है और 5 पेन ₹80 में बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["28%","25%","30%","20%"],"explanationHi":"प्रति पेन क्रय मूल्य = 100/8 = ₹12.50 और प्रति पेन विक्रय मूल्य = 80/5 = ₹16। लाभ = 3.50/12.50 = 28%।","subtopic":"articles-ratio","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-179","question":"After a 20% discount on the marked price a shopkeeper still earns a profit of 12%. What would his profit percentage be if he sold at the marked price?","options":["40%","32%","36%","44%"],"answer":0,"explanation":"0.8M = 1.12c gives M = 1.4c, so selling at the marked price gives a 40% profit.","difficulty":"moderate","questionHi":"अंकित मूल्य पर 20% छूट देने के बाद भी एक दुकानदार को 12% लाभ होता है। यदि वह अंकित मूल्य पर बेचे, तो उसका लाभ प्रतिशत क्या होगा?","optionsHi":["40%","32%","36%","44%"],"explanationHi":"0.8M = 1.12c से M = 1.4c, अतः अंकित मूल्य पर बेचने से 40% लाभ होता है।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-180","question":"A trader marks an article 50% above its cost. What discount on the marked price would leave him with an 8% profit?","options":["24%","30%","28%","32%"],"answer":2,"explanation":"With CP = 100, MP = 150 and the required SP = 108. Discount = (150 − 108)/150 = 28%. Subtracting 50 − 8 = 42 and stopping there is the usual error.","difficulty":"hard","questionHi":"एक व्यापारी एक वस्तु पर क्रय मूल्य से 50% ऊपर अंकित मूल्य लिखता है। अंकित मूल्य पर कितनी छूट देने से उसे 8% लाभ रहेगा?","optionsHi":["24%","30%","28%","32%"],"explanationHi":"क्रय मूल्य = 100 लें, तो अंकित मूल्य = 150 और अपेक्षित विक्रय मूल्य = 108। छूट = (150 − 108)/150 = 28%। 50 − 8 = 42 पर रुक जाना सामान्य भूल है।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-181","question":"At a 25% discount on the marked price a shopkeeper earns a 20% profit. What discount on the marked price would give him a 30% profit?","options":["15%","18.75%","20%","17.5%"],"answer":1,"explanation":"0.75M = 1.2c gives M = 1.6c. For a 30% profit SP = 1.3c, so the discount is (1.6 − 1.3)/1.6 = 18.75%.","difficulty":"very-hard","questionHi":"अंकित मूल्य पर 25% छूट देने पर एक दुकानदार को 20% लाभ होता है। अंकित मूल्य पर कितनी छूट देने से उसे 30% लाभ होगा?","optionsHi":["15%","18.75%","20%","17.5%"],"explanationHi":"0.75M = 1.2c से M = 1.6c। 30% लाभ के लिए विक्रय मूल्य = 1.3c, अतः छूट = (1.6 − 1.3)/1.6 = 18.75%।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-182","question":"A shopkeeper offers 'buy 3 get 1 free' on an article marked at ₹960, so 4 articles are sold for the price of 3. If this still gives him a profit of 20% on each article, what is its cost price?","options":["₹800","₹640","₹750","₹600"],"answer":3,"explanation":"Four articles fetch 3 × 960 = ₹2,880, i.e. ₹720 each. This is 120% of the cost, so CP = 720/1.2 = ₹600.","difficulty":"hard","questionHi":"एक दुकानदार ₹960 अंकित मूल्य वाली वस्तु पर '3 खरीदें, 1 मुफ़्त पाएँ' की योजना देता है, यानी 3 के मूल्य पर 4 वस्तुएँ बिकती हैं। यदि इससे भी प्रत्येक वस्तु पर 20% लाभ होता है, तो उसका क्रय मूल्य क्या है?","optionsHi":["₹800","₹640","₹750","₹600"],"explanationHi":"चार वस्तुओं से 3 × 960 = ₹2,880 मिलते हैं, यानी प्रति वस्तु ₹720। यह क्रय मूल्य का 120% है, अतः क्रय मूल्य = 720/1.2 = ₹600।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-183","question":"A shopkeeper marks an article 40% above its cost and sells it for ₹1,680 after allowing a 20% discount. What is his profit percentage?","options":["20%","15%","12%","8%"],"answer":2,"explanation":"Marked price = 1,680/0.8 = ₹2,100, so cost = 2,100/1.4 = ₹1,500. Profit = 180/1,500 = 12%. Equivalently 1.4 × 0.8 = 1.12.","difficulty":"hard","questionHi":"एक दुकानदार एक वस्तु पर क्रय मूल्य से 40% ऊपर अंकित मूल्य लिखता है और 20% छूट देकर उसे ₹1,680 में बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","15%","12%","8%"],"explanationHi":"अंकित मूल्य = 1,680/0.8 = ₹2,100, अतः क्रय मूल्य = 2,100/1.4 = ₹1,500। लाभ = 180/1,500 = 12%। इसी प्रकार 1.4 × 0.8 = 1.12।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-184","question":"A shopkeeper allows a 20% discount on an article marked at ₹900 and still gains 25%. What is the cost price?","options":["₹576","₹600","₹625","₹540"],"answer":0,"explanation":"Selling price = 900 × 0.8 = ₹720, which is 125% of the cost, so CP = 720/1.25 = ₹576.","difficulty":"moderate","questionHi":"एक दुकानदार ₹900 अंकित मूल्य वाली वस्तु पर 20% छूट देता है और फिर भी 25% लाभ कमाता है। क्रय मूल्य क्या है?","optionsHi":["₹576","₹600","₹625","₹540"],"explanationHi":"विक्रय मूल्य = 900 × 0.8 = ₹720, जो क्रय मूल्य का 125% है, अतः क्रय मूल्य = 720/1.25 = ₹576।","subtopic":"marked-price-discount","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-185","question":"Successive discounts of 20%, 10% and x% are together equal to a single discount of 40%. What is x?","options":["10%","15%","20%","16.67%"],"answer":3,"explanation":"0.8 × 0.9 × (1 − x/100) = 0.6 gives 1 − x/100 = 0.6/0.72 = 5/6, so x = 16.67%.","difficulty":"hard","questionHi":"20%, 10% और x% की क्रमागत छूटें मिलकर 40% की एकल छूट के बराबर हैं। x का मान क्या है?","optionsHi":["10%","15%","20%","16.67%"],"explanationHi":"0.8 × 0.9 × (1 − x/100) = 0.6 से 1 − x/100 = 0.6/0.72 = 5/6, अतः x = 16.67%।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-186","question":"A shop gives a 25% discount on the marked price and a further 10% off for festival customers. A customer pays ₹1,350. What is the marked price?","options":["₹1,800","₹2,000","₹2,250","₹2,400"],"answer":1,"explanation":"The net factor is 0.75 × 0.9 = 0.675, so the marked price = 1,350/0.675 = ₹2,000.","difficulty":"moderate","questionHi":"एक दुकान अंकित मूल्य पर 25% छूट और त्योहार के ग्राहकों को 10% की अतिरिक्त छूट देती है। एक ग्राहक ₹1,350 चुकाता है। अंकित मूल्य क्या है?","optionsHi":["₹1,800","₹2,000","₹2,250","₹2,400"],"explanationHi":"कुल गुणक 0.75 × 0.9 = 0.675 है, अतः अंकित मूल्य = 1,350/0.675 = ₹2,000।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-187","question":"Which of these schemes gives the customer the greatest total discount?","options":["A single discount of 35%","20%, 15% and 5% in succession","30% followed by 7%","25% followed by 13%"],"answer":1,"explanation":"Net discounts are 35% (single), 34.9% (0.7 × 0.93), 35.4% (0.8 × 0.85 × 0.95 = 0.646) and 34.75% (0.75 × 0.87). The three-step scheme is best.","difficulty":"very-hard","questionHi":"इनमें से कौन-सी योजना ग्राहक को सबसे अधिक कुल छूट देती है?","optionsHi":["35% की एकल छूट","क्रमशः 20%, 15% और 5%","30% के बाद 7%","25% के बाद 13%"],"explanationHi":"कुल छूटें 35% (एकल), 34.9% (0.7 × 0.93), 35.4% (0.8 × 0.85 × 0.95 = 0.646) और 34.75% (0.75 × 0.87) हैं। तीन-चरणीय योजना सबसे अच्छी है।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-188","question":"A store gives 20% off every item, and a further 10% off the discounted bill if that bill exceeds ₹5,000. A customer whose items are marked at ₹6,200 adds items marked at ₹100 more. How does his final bill change?","options":["It rises by ₹80","It falls by ₹504","It falls by ₹400","It falls by ₹424"],"answer":3,"explanation":"At ₹6,200 the bill is 6,200 × 0.8 = ₹4,960, below ₹5,000, so no extra discount. At ₹6,300 it is 5,040, which exceeds 5,000, so the bill is 5,040 × 0.9 = ₹4,536. It falls by 4,960 − 4,536 = ₹424.","difficulty":"hard","questionHi":"एक दुकान प्रत्येक वस्तु पर 20% छूट देती है और यदि छूट के बाद का बिल ₹5,000 से अधिक हो तो उस पर 10% की और छूट देती है। जिस ग्राहक की वस्तुओं का अंकित मूल्य ₹6,200 है, वह ₹100 अंकित मूल्य की और वस्तुएँ जोड़ लेता है। उसका अंतिम बिल कैसे बदलता है?","optionsHi":["₹80 बढ़ता है","₹504 घटता है","₹400 घटता है","₹424 घटता है"],"explanationHi":"₹6,200 पर बिल 6,200 × 0.8 = ₹4,960 है, जो ₹5,000 से कम है, अतः अतिरिक्त छूट नहीं। ₹6,300 पर बिल 5,040 है, जो 5,000 से अधिक है, इसलिए बिल 5,040 × 0.9 = ₹4,536। यह 4,960 − 4,536 = ₹424 घटता है।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-189","question":"What single discount is equivalent to three successive discounts of 10%, 20% and 30%?","options":["49.6%","60%","50%","48.6%"],"answer":0,"explanation":"The net factor is 0.9 × 0.8 × 0.7 = 0.504, so the equivalent discount is 100 − 50.4 = 49.6%. Adding the rates gives 60%.","difficulty":"hard","questionHi":"10%, 20% और 30% की तीन क्रमागत छूटों के तुल्य एकल छूट क्या है?","optionsHi":["49.6%","60%","50%","48.6%"],"explanationHi":"कुल गुणक 0.9 × 0.8 × 0.7 = 0.504 है, अतः तुल्य छूट 100 − 50.4 = 49.6%। दरें जोड़ने पर 60% आता है।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-190","question":"Assertion (A): Successive discounts of 10% and 20% give the same final price whichever discount is applied first. Reason (R): The net multiplying factor is the product 0.9 × 0.8, and multiplication does not depend on order.","options":["Both A and R are true but R does not explain A","A is true but R is false","Both A and R are true and R explains A","A is false but R is true"],"answer":2,"explanation":"Each discount multiplies the price by (1 − rate), so the final price is P × 0.9 × 0.8 = 0.72P in either order. Hence A is true and R is exactly why.","difficulty":"moderate","questionHi":"अभिकथन (A): 10% और 20% की क्रमागत छूटों में चाहे कोई भी छूट पहले दी जाए, अंतिम मूल्य समान रहता है। कारण (R): कुल गुणक गुणनफल 0.9 × 0.8 है, और गुणन क्रम पर निर्भर नहीं करता।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की व्याख्या नहीं करता","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A असत्य है परंतु R सत्य है"],"explanationHi":"प्रत्येक छूट मूल्य को (1 − दर) से गुणा करती है, अतः दोनों क्रमों में अंतिम मूल्य P × 0.9 × 0.8 = 0.72P होता है। इसलिए A सत्य है और R ही इसका कारण है।","subtopic":"successive-discounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-191","question":"A dealer buys at ₹100 per kg, marks the price 20% above cost and allows a 10% discount, but gives only 950 g for each kg sold. What is his overall profit percentage?","options":["8%","5.26%","13.26%","13.68%"],"answer":3,"explanation":"Per 'kg' he receives 120 × 0.9 = ₹108, while the 950 g he actually hands over costs 95. Profit = 13/95 = 13.68%.","difficulty":"very-hard","questionHi":"एक व्यापारी ₹100 प्रति kg पर खरीदता है, क्रय मूल्य से 20% ऊपर अंकित मूल्य लिखता है और 10% छूट देता है, परंतु प्रत्येक बेचे गए kg के लिए केवल 950 g देता है। उसका कुल लाभ प्रतिशत क्या है?","optionsHi":["8%","5.26%","13.26%","13.68%"],"explanationHi":"प्रति 'kg' उसे 120 × 0.9 = ₹108 मिलते हैं, जबकि वह वास्तव में 950 g देता है जिसकी लागत 95 है। लाभ = 13/95 = 13.68%।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-192","question":"A milkman buys milk at ₹50 per litre, adds water so that the mixture is 20% water and sells the mixture at ₹50 per litre. What is his profit percentage?","options":["20%","25%","16.67%","33.33%"],"answer":1,"explanation":"One litre of mixture holds only 0.8 L of milk, costing ₹40, yet sells for ₹50. Profit = 10/40 = 25% (not 20%).","difficulty":"moderate","questionHi":"एक दूधवाला ₹50 प्रति लीटर पर दूध खरीदता है, उसमें पानी मिलाकर मिश्रण में 20% पानी कर देता है और मिश्रण को ₹50 प्रति लीटर पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["20%","25%","16.67%","33.33%"],"explanationHi":"एक लीटर मिश्रण में केवल 0.8 L दूध होता है, जिसकी लागत ₹40 है, पर वह ₹50 में बिकता है। लाभ = 10/40 = 25% (20% नहीं)।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-193","question":"A dealer uses an 800 g weight in place of 1 kg and sells at 10% below his cost price per kg. What is his profit percentage?","options":["10%","25%","12.5%","15%"],"answer":2,"explanation":"Let cost = ₹100 per kg. He receives 100 × 0.9 = ₹90 per 'kg' but hands over only 800 g costing ₹80. Profit = 10/80 = 12.5%.","difficulty":"very-hard","questionHi":"एक व्यापारी 1 kg के स्थान पर 800 g का बाट प्रयोग करता है और अपने प्रति kg क्रय मूल्य से 10% कम पर बेचता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["10%","25%","12.5%","15%"],"explanationHi":"मान लें क्रय मूल्य ₹100 प्रति kg है। प्रति 'kg' उसे 100 × 0.9 = ₹90 मिलते हैं पर वह केवल 800 g देता है जिसकी लागत ₹80 है। लाभ = 10/80 = 12.5%।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-194","question":"A dealer buys goods using a 1,200 g weight for each kg and sells using a 900 g weight for each kg, charging the same per-kg price at which he bought. What is his profit percentage?","options":["33.33%","11.11%","20%","25%"],"answer":0,"explanation":"For ₹100 he receives 1.2 kg actual, which he sells as 1.2/0.9 = 4/3 'kg' at ₹100 each, i.e. ₹133.33. Profit = 33.33%.","difficulty":"very-hard","questionHi":"एक व्यापारी माल खरीदते समय प्रत्येक kg के लिए 1,200 g का बाट और बेचते समय प्रत्येक kg के लिए 900 g का बाट प्रयोग करता है, और उसी प्रति-kg मूल्य पर बेचता है जिस पर उसने खरीदा था। उसका लाभ प्रतिशत क्या है?","optionsHi":["33.33%","11.11%","20%","25%"],"explanationHi":"₹100 में उसे वास्तव में 1.2 kg मिलता है, जिसे वह 1.2/0.9 = 4/3 'kg' के रूप में ₹100 प्रति kg पर बेचता है, यानी ₹133.33। लाभ = 33.33%।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-195","question":"A dealer sells at the cost price per kg but uses a false weight, and in this way gains 20%. What weight does he use in place of 1 kg?","options":["833.33 g","800 g","850 g","880 g"],"answer":0,"explanation":"Profit % = (1000 − w)/w × 100 = 20 gives 1000 − w = 0.2w, so w = 1000/1.2 = 833.33 g. The weight 800 g would give a 25% gain.","difficulty":"hard","questionHi":"एक व्यापारी प्रति kg क्रय मूल्य पर बेचता है पर झूठे बाट का प्रयोग करता है और इस प्रकार 20% लाभ कमाता है। वह 1 kg के स्थान पर कितने भार का बाट प्रयोग करता है?","optionsHi":["833.33 g","800 g","850 g","880 g"],"explanationHi":"लाभ % = (1000 − w)/w × 100 = 20 से 1000 − w = 0.2w, अतः w = 1000/1.2 = 833.33 g। 800 g के बाट से 25% लाभ होता।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-196","question":"A shopkeeper buys sugar at ₹40 per kg and sells it at ₹44 per 'kg' while using an 880 g weight for each kg. What is his profit percentage?","options":["10%","22.5%","25%","12%"],"answer":2,"explanation":"The 880 g he actually gives costs 40 × 0.88 = ₹35.20 and he receives ₹44. Profit = 8.80/35.20 = 25%.","difficulty":"very-hard","questionHi":"एक दुकानदार चीनी ₹40 प्रति kg पर खरीदता है और प्रति 'kg' ₹44 पर बेचता है, जबकि प्रत्येक kg के लिए 880 g का बाट प्रयोग करता है। उसका लाभ प्रतिशत क्या है?","optionsHi":["10%","22.5%","25%","12%"],"explanationHi":"वास्तव में दिए गए 880 g की लागत 40 × 0.88 = ₹35.20 है और उसे ₹44 मिलते हैं। लाभ = 8.80/35.20 = 25%।","subtopic":"dishonest-dealer","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-197","question":"A sells an article to B at a profit of 20%, and B sells it to C at a profit of 25%. If C pays ₹1,350, what did the article cost A?","options":["₹931","₹900","₹1,080","₹1,125"],"answer":1,"explanation":"The net factor is 1.2 × 1.25 = 1.5, so A's cost = 1,350/1.5 = ₹900. Adding the rates (45%) would give about ₹931.","difficulty":"moderate","questionHi":"A एक वस्तु B को 20% लाभ पर बेचता है और B उसे C को 25% लाभ पर बेचता है। यदि C ₹1,350 चुकाता है, तो A के लिए वस्तु का क्रय मूल्य क्या था?","optionsHi":["₹931","₹900","₹1,080","₹1,125"],"explanationHi":"कुल गुणक 1.2 × 1.25 = 1.5 है, अतः A का क्रय मूल्य = 1,350/1.5 = ₹900। दरें जोड़ने (45%) पर लगभग ₹931 आता।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-198","question":"A sells an article to B at a loss of 10%, B sells it to C at a profit of 20%, and C sells it to D at a profit of 25%. If D pays ₹5,400, what did the article cost A?","options":["₹4,500","₹4,320","₹3,600","₹4,000"],"answer":3,"explanation":"The net factor is 0.9 × 1.2 × 1.25 = 1.35, so A's cost = 5,400/1.35 = ₹4,000.","difficulty":"very-hard","questionHi":"A एक वस्तु B को 10% हानि पर बेचता है, B उसे C को 20% लाभ पर बेचता है और C उसे D को 25% लाभ पर बेचता है। यदि D ₹5,400 चुकाता है, तो A के लिए वस्तु का क्रय मूल्य क्या था?","optionsHi":["₹4,500","₹4,320","₹3,600","₹4,000"],"explanationHi":"कुल गुणक 0.9 × 1.2 × 1.25 = 1.35 है, अतः A का क्रय मूल्य = 5,400/1.35 = ₹4,000।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-199","question":"A sells an article to B at a profit of 25%, and B sells it to C at a loss of 20%. If C pays ₹4,800, what did the article cost A?","options":["₹6,000","₹3,840","₹4,800","₹4,000"],"answer":2,"explanation":"The net factor is 1.25 × 0.8 = 1, so A's cost equals what C pays, ₹4,800. A 25% profit followed by a 20% loss cancels out exactly.","difficulty":"very-hard","questionHi":"A एक वस्तु B को 25% लाभ पर बेचता है और B उसे C को 20% हानि पर बेचता है। यदि C ₹4,800 चुकाता है, तो A के लिए वस्तु का क्रय मूल्य क्या था?","optionsHi":["₹6,000","₹3,840","₹4,800","₹4,000"],"explanationHi":"कुल गुणक 1.25 × 0.8 = 1 है, अतः A का क्रय मूल्य C द्वारा चुकाई राशि ₹4,800 के बराबर है। 25% लाभ के बाद 20% हानि ठीक एक-दूसरे को काट देती है।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-200","question":"A sells an article to B at a profit of 20%, and B sells it to C at a profit of 15%. If B's profit is ₹270, what did the article cost A?","options":["₹1,500","₹1,350","₹1,800","₹1,125"],"answer":0,"explanation":"B's cost = 1.2a and his profit is 15% of that = 0.18a = 270, so a = ₹1,500. The figure ₹1,800 is B's cost, not A's.","difficulty":"hard","questionHi":"A एक वस्तु B को 20% लाभ पर बेचता है और B उसे C को 15% लाभ पर बेचता है। यदि B का लाभ ₹270 है, तो A के लिए वस्तु का क्रय मूल्य क्या था?","optionsHi":["₹1,500","₹1,350","₹1,800","₹1,125"],"explanationHi":"B का क्रय मूल्य = 1.2a और उसका लाभ उसका 15% = 0.18a = 270, अतः a = ₹1,500। ₹1,800 B का क्रय मूल्य है, A का नहीं।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-201","question":"A sells an article to B at a profit of 10%, B sells it to C at a profit of 20%, and C sells it to D at a loss of 25%. If D pays ₹4,950, what did the article cost A?","options":["₹4,500","₹5,500","₹4,950","₹5,000"],"answer":3,"explanation":"The net factor is 1.1 × 1.2 × 0.75 = 0.99, so A's cost = 4,950/0.99 = ₹5,000. Despite two profits the chain ends with a 1% net loss.","difficulty":"hard","questionHi":"A एक वस्तु B को 10% लाभ पर बेचता है, B उसे C को 20% लाभ पर बेचता है और C उसे D को 25% हानि पर बेचता है। यदि D ₹4,950 चुकाता है, तो A के लिए वस्तु का क्रय मूल्य क्या था?","optionsHi":["₹4,500","₹5,500","₹4,950","₹5,000"],"explanationHi":"कुल गुणक 1.1 × 1.2 × 0.75 = 0.99 है, अतः A का क्रय मूल्य = 4,950/0.99 = ₹5,000। दो लाभों के बावजूद शृंखला का अंत 1% की कुल हानि पर होता है।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-202","question":"A sells a cycle to B at a loss of 20%. B sells it to C for ₹5,040, gaining 5%. What did the cycle cost A?","options":["₹5,760","₹6,000","₹5,040","₹6,300"],"answer":1,"explanation":"B's cost = 5,040/1.05 = ₹4,800, which is A's selling price = 0.8 × A's cost. So A's cost = 4,800/0.8 = ₹6,000.","difficulty":"hard","questionHi":"A एक साइकिल B को 20% हानि पर बेचता है। B उसे C को ₹5,040 में बेचकर 5% लाभ कमाता है। A के लिए साइकिल का क्रय मूल्य क्या था?","optionsHi":["₹5,760","₹6,000","₹5,040","₹6,300"],"explanationHi":"B का क्रय मूल्य = 5,040/1.05 = ₹4,800, जो A का विक्रय मूल्य = 0.8 × A का क्रय मूल्य है। अतः A का क्रय मूल्य = 4,800/0.8 = ₹6,000।","subtopic":"successive-selling","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-203","question":"Two articles are sold for ₹2,400 each, one at a profit of 25% and the other at a loss of 25%. What is the overall result?","options":["Profit of ₹320","Loss of ₹320","Loss of ₹160","No profit, no loss"],"answer":1,"explanation":"Costs are 2,400/1.25 = ₹1,920 and 2,400/0.75 = ₹3,200, total ₹5,120 against receipts of ₹4,800. The loss is ₹320 (6.25%).","difficulty":"hard","questionHi":"दो वस्तुएँ ₹2,400 प्रति वस्तु की दर से बेची जाती हैं, एक 25% लाभ पर और दूसरी 25% हानि पर। कुल परिणाम क्या है?","optionsHi":["₹320 का लाभ","₹320 की हानि","₹160 की हानि","न लाभ, न हानि"],"explanationHi":"क्रय मूल्य 2,400/1.25 = ₹1,920 और 2,400/0.75 = ₹3,200 हैं, कुल ₹5,120 जबकि प्राप्ति ₹4,800। हानि ₹320 (6.25%) है।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-204","question":"A trader earns a 20% profit on one lot of goods and suffers a 10% loss on another lot, and overall he makes a 4% profit. What is the ratio of the cost prices of the two lots?","options":["8 : 7","3 : 2","5 : 4","7 : 8"],"answer":3,"explanation":"By alligation, the distances of 20 and −10 from the mean 4 are 16 and 14. The cost ratio of the profit lot to the loss lot is the inverse, 14 : 16 = 7 : 8.","difficulty":"very-hard","questionHi":"एक व्यापारी माल की एक खेप पर 20% लाभ कमाता है और दूसरी खेप पर 10% हानि उठाता है, और कुल मिलाकर उसे 4% लाभ होता है। दोनों खेपों के क्रय मूल्यों का अनुपात क्या है?","optionsHi":["8 : 7","3 : 2","5 : 4","7 : 8"],"explanationHi":"मिश्रण-विधि से 20 और −10 की औसत 4 से दूरियाँ 16 और 14 हैं। लाभ वाली खेप और हानि वाली खेप के क्रय मूल्यों का अनुपात इसका उल्टा, 14 : 16 = 7 : 8 है।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-205","question":"A trader buys goods worth ₹4,000, sells a part at a 10% profit and the rest at a 5% loss, and earns an overall profit of 4%. What was the cost of the part sold at a profit?","options":["₹2,400","₹1,600","₹2,000","₹3,000"],"answer":0,"explanation":"Let the profitable part cost x: 0.10x − 0.05(4,000 − x) = 0.04 × 4,000 = 160 gives 0.15x = 360, so x = ₹2,400.","difficulty":"very-hard","questionHi":"एक व्यापारी ₹4,000 का माल खरीदता है, उसका एक भाग 10% लाभ पर और शेष 5% हानि पर बेचता है, और कुल 4% लाभ कमाता है। लाभ पर बेचे गए भाग की लागत कितनी थी?","optionsHi":["₹2,400","₹1,600","₹2,000","₹3,000"],"explanationHi":"लाभ वाले भाग की लागत x मानें: 0.10x − 0.05(4,000 − x) = 0.04 × 4,000 = 160 से 0.15x = 360, अतः x = ₹2,400।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-206","question":"Two articles are sold at the same price, one at a gain of 25% and the other at a loss of 20%. What is the overall result?","options":["2.5% loss","5% loss","2.44% loss","2.44% profit"],"answer":2,"explanation":"With SP = s each, the costs are s/1.25 = 0.8s and s/0.8 = 1.25s, total 2.05s against receipts of 2s. Loss = 0.05/2.05 = 2.44%.","difficulty":"very-hard","questionHi":"दो वस्तुएँ एक ही मूल्य पर बेची जाती हैं, एक 25% लाभ पर और दूसरी 20% हानि पर। कुल परिणाम क्या है?","optionsHi":["2.5% हानि","5% हानि","2.44% हानि","2.44% लाभ"],"explanationHi":"प्रत्येक का विक्रय मूल्य s होने पर क्रय मूल्य s/1.25 = 0.8s और s/0.8 = 1.25s हैं, कुल 2.05s जबकि प्राप्ति 2s। हानि = 0.05/2.05 = 2.44%।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-207","question":"A merchant sells 40% of his rice at a 25% profit, another 40% at a 5% profit and the rest at x% profit, earning an overall profit of 20%. What is x? (Quantities are of equal cost per kg.)","options":["30%","35%","25%","40%"],"answer":3,"explanation":"0.4 × 25 + 0.4 × 5 + 0.2x = 20 gives 10 + 2 + 0.2x = 20, so x = 40%.","difficulty":"hard","questionHi":"एक व्यापारी अपने चावल का 40% भाग 25% लाभ पर, अन्य 40% भाग 5% लाभ पर और शेष x% लाभ पर बेचता है और कुल 20% लाभ कमाता है। x का मान क्या है? (प्रति kg लागत समान है।)","optionsHi":["30%","35%","25%","40%"],"explanationHi":"0.4 × 25 + 0.4 × 5 + 0.2x = 20 से 10 + 2 + 0.2x = 20, अतः x = 40%।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-profit-loss-208","question":"A fruit seller buys 40 kg of apples at ₹60 per kg and 60 kg of better apples at ₹80 per kg, and mixes them. At what price per kg must he sell the mixture to earn an overall profit of 25%?","options":["₹87.50","₹90","₹100","₹84"],"answer":1,"explanation":"Total cost = 2,400 + 4,800 = ₹7,200 for 100 kg, i.e. ₹72 per kg. Selling price for 25% profit = 72 × 1.25 = ₹90. The simple average of 60 and 80 would wrongly give ₹87.50.","difficulty":"hard","questionHi":"एक फल विक्रेता ₹60 प्रति kg पर 40 kg सेब और ₹80 प्रति kg पर 60 kg बेहतर सेब खरीदकर उन्हें मिला देता है। 25% कुल लाभ कमाने के लिए उसे मिश्रण को प्रति kg किस मूल्य पर बेचना चाहिए?","optionsHi":["₹87.50","₹90","₹100","₹84"],"explanationHi":"कुल लागत = 2,400 + 4,800 = ₹7,200, 100 kg के लिए, अर्थात् ₹72 प्रति kg। 25% लाभ के लिए विक्रय मूल्य = 72 × 1.25 = ₹90। 60 और 80 का साधारण औसत लेने पर गलत रूप से ₹87.50 आता।","subtopic":"combined-transactions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
